import type { MenuSteps } from "./menuStepsTypes";

export const MONITOR_STEPS: MenuSteps = {
  overview: [
    { target: "ov-mode", placement: "bottom",
      t: ["The big arming button", "El botón grande de armado", "Der große Scharfschalt-Knopf", "Le gros bouton d'armement", "Il grande pulsante di inserimento", "大きな警戒ボタン", "醒目的布防按钮", "O botão grande de armar"],
      b: ["Here you see whether the system is armed and you change it. Arming first asks the server to check the perimeter and lists what would leave it blind (a node that does not answer, an open zone, a camera that is down); you can arm anyway, but nothing is armed until you confirm. Disarming asks for your PIN. A common mistake is arming with a door open: read the list before confirming.",
        "Aquí ves si el sistema está armado y lo cambias. Al armar, el servidor comprueba antes el perímetro y lista lo que lo dejaría ciego (un nodo que no responde, una zona abierta, una cámara caída); puedes armar igualmente, pero nada se arma hasta que confirmes. Desarmar pide tu PIN. Un error habitual es armar con una puerta abierta: lee la lista antes de confirmar.",
        "Hier sehen Sie, ob das System scharf ist, und schalten um. Beim Scharfschalten lässt der Server zuerst den Perimeter prüfen und listet, was ihn blind ließe (ein Knoten ohne Antwort, eine offene Zone, eine ausgefallene Kamera); Sie können trotzdem scharf schalten, aber erst nach Ihrer Bestätigung. Das Unscharfschalten verlangt Ihre PIN. Ein häufiger Fehler: scharf schalten bei offener Tür - lesen Sie die Liste vor dem Bestätigen.",
        "Ici vous voyez si le système est armé et vous le changez. Pour armer, le serveur vérifie d'abord le périmètre et liste ce qui le laisserait aveugle (un nœud muet, une zone ouverte, une caméra hors service) ; vous pouvez armer quand même, mais rien n'est armé avant votre confirmation. Désarmer demande votre PIN. Erreur fréquente : armer avec une porte ouverte, lisez la liste avant de confirmer.",
        "Qui vedi se il sistema è inserito e lo cambi. Prima di inserire, il server controlla il perimetro ed elenca ciò che lo lascerebbe cieco (un nodo che non risponde, una zona aperta, una telecamera spenta); puoi inserire comunque, ma nulla è inserito finché non confermi. Disinserire chiede il tuo PIN. Errore comune: inserire con una porta aperta, leggi l'elenco prima di confermare.",
        "システムが警戒中かどうかを確認し、切り替えます。警戒する前にサーバーが境界を点検し、盲点になるもの（応答しないノード、開いたゾーン、停止したカメラ）を一覧にします。そのまま警戒することもできますが、確認するまで警戒されません。解除にはPINが必要です。よくある間違いはドアが開いたまま警戒すること。確認前に一覧を読んでください。",
        "在这里查看系统是否已布防，并切换状态。布防前服务器会先检查周界，列出会留下盲区的情况（无响应的节点、打开的分区、离线的摄像头）；你可以强制布防，但在确认之前不会布防。撤防需要输入 PIN。常见错误是门没关就布防：确认前请先看清列表。",
        "Aqui vê se o sistema está armado e altera-o. Ao armar, o servidor verifica primeiro o perímetro e lista o que o deixaria cego (um nó que não responde, uma zona aberta, uma câmara em baixo); pode armar mesmo assim, mas nada fica armado até confirmar. Desarmar pede o seu PIN. Um erro comum é armar com uma porta aberta: leia a lista antes de confirmar."] },
    { target: "ov-tiles", placement: "bottom",
      t: ["The tiles: eight areas at a glance", "Las fichas: ocho áreas de un vistazo", "Die Kacheln: acht Bereiche auf einen Blick", "Les tuiles : huit domaines d'un coup d'œil", "Le schede: otto aree a colpo d'occhio", "タイル：8つの領域を一目で", "卡片：八个区域一目了然", "Os cartões: oito áreas de relance"],
      b: ["Alarms, alarm panels, radar, cameras, devices, energy, network and system, each with its main number and a line under it. A tile turns red or amber when something is wrong (a panel sounding, a device triggered, the internet down). Click a tile to open its menu. If a tile shows a dash, that part has not reported yet: it is not an error by itself.",
        "Alarmas, centrales, radar, cámaras, dispositivos, energía, red y sistema, cada una con su cifra principal y una línea debajo. Una ficha se pone roja o ámbar cuando algo va mal (una central sonando, un dispositivo disparado, internet caído). Haz clic en una ficha para abrir su menú. Si una ficha muestra un guion, esa parte aún no ha informado: por sí solo no es un error.",
        "Alarme, Alarmzentralen, Radar, Kameras, Geräte, Energie, Netz und System, jeweils mit der wichtigsten Zahl und einer Zeile darunter. Eine Kachel wird rot oder bernsteinfarben, wenn etwas nicht stimmt (eine Zentrale heult, ein Gerät hat ausgelöst, das Internet ist weg). Ein Klick öffnet das Menü. Zeigt eine Kachel einen Strich, hat dieser Teil noch nicht berichtet: das allein ist kein Fehler.",
        "Alarmes, centrales, radar, caméras, appareils, énergie, réseau et système, chacune avec son chiffre principal et une ligne dessous. Une tuile devient rouge ou orange quand quelque chose ne va pas (une centrale qui sonne, un appareil déclenché, Internet coupé). Un clic ouvre son menu. Si une tuile affiche un tiret, cette partie n'a pas encore rapporté : ce n'est pas une erreur en soi.",
        "Allarmi, centrali, radar, telecamere, dispositivi, energia, rete e sistema, ognuna con il suo numero principale e una riga sotto. Una scheda diventa rossa o ambra quando qualcosa non va (una centrale che suona, un dispositivo scattato, internet assente). Un clic apre il suo menu. Se una scheda mostra un trattino, quella parte non ha ancora riferito: di per sé non è un errore.",
        "アラーム、警報制御盤、レーダー、カメラ、デバイス、エネルギー、ネットワーク、システムの8つ。それぞれ主な数値と補足の1行があります。異常（制御盤が鳴動中、デバイスが作動、インターネット断）のときは赤や橙色になります。クリックでそのメニューが開きます。ダッシュ表示はまだ報告がないだけで、それ自体はエラーではありません。",
        "报警、报警主机、雷达、摄像头、设备、能源、网络和系统，每张卡片都有主要数字和下方的一行说明。出现问题时（主机鸣响、设备触发、互联网中断）卡片会变红或变橙。点击卡片即可打开对应菜单。若显示短横线，说明该部分尚未上报，这本身不是错误。",
        "Alarmes, centrais, radar, câmaras, dispositivos, energia, rede e sistema, cada um com o seu número principal e uma linha por baixo. Um cartão fica vermelho ou âmbar quando algo corre mal (uma central a tocar, um dispositivo disparado, a internet em baixo). Um clique abre o respetivo menu. Se um cartão mostra um traço, essa parte ainda não comunicou: por si só não é um erro."] },
    { target: "ov-map", placement: "right",
      t: ["The live map", "El mapa en vivo", "Die Live-Karte", "La carte en direct", "La mappa dal vivo", "ライブマップ", "实时地图", "O mapa em direto"],
      b: ["Your site design in small, with the radar targets moving as they are seen and the devices where you placed them. An alarm nobody has acknowledged pulses where its camera, device or radar is drawn (red critical, orange high, yellow warning). \"Site designer\" opens the drawing. If the map is empty, nothing has been drawn yet: start in the Site designer.",
        "Tu diseño del sitio en pequeño, con los blancos del radar moviéndose según se ven y los dispositivos donde los colocaste. Una alarma sin reconocer late donde está dibujada su cámara, dispositivo o radar (roja crítica, naranja alta, amarilla aviso). \"Diseñador\" abre el dibujo. Si el mapa está vacío, aún no hay nada dibujado: empieza en el Diseñador de emplazamiento.",
        "Ihr Standortentwurf in klein, mit den Radarzielen, die sich so bewegen, wie sie gesehen werden, und den Geräten dort, wo Sie sie platziert haben. Ein nicht quittierter Alarm pulsiert dort, wo seine Kamera, sein Gerät oder sein Radar gezeichnet ist (rot kritisch, orange hoch, gelb Warnung). Der Link öffnet den Designer. Ist die Karte leer, wurde noch nichts gezeichnet: beginnen Sie im Standort-Designer.",
        "Votre plan du site en petit, avec les cibles du radar qui bougent comme elles sont vues et les appareils là où vous les avez placés. Une alarme non acquittée pulse là où sa caméra, son appareil ou son radar est dessiné (rouge critique, orange élevée, jaune avertissement). Le lien ouvre le concepteur. Si la carte est vide, rien n'est encore dessiné : commencez par le concepteur de site.",
        "Il progetto del sito in piccolo, con i bersagli del radar che si muovono come vengono visti e i dispositivi dove li hai messi. Un allarme non riconosciuto pulsa dove è disegnata la sua telecamera, il dispositivo o il radar (rosso critico, arancione alto, giallo avviso). Il collegamento apre il progettista. Se la mappa è vuota, non c'è ancora nulla di disegnato: parti dal progettista del sito.",
        "サイト設計を縮小表示し、レーダーの対象が見えた通りに動き、デバイスは配置した場所に出ます。未確認のアラームは、そのカメラ・デバイス・レーダーの位置で脈打ちます（赤＝重大、橙＝高、黄＝警告）。リンクから設計画面を開けます。地図が空ならまだ何も描かれていません。サイト設計から始めてください。",
        "缩小显示你的场地设计，雷达目标随被发现而移动，设备位于你放置的位置。未确认的报警会在其摄像头、设备或雷达所在处闪动（红色严重、橙色高、黄色警告）。链接可打开设计器。如果地图是空的，说明还没画任何东西：请先到场地设计器。",
        "O desenho do local em ponto pequeno, com os alvos do radar a mexerem-se como são vistos e os dispositivos onde os colocou. Um alarme por reconhecer pulsa onde está desenhada a sua câmara, dispositivo ou radar (vermelho crítico, laranja alto, amarelo aviso). A ligação abre o desenhador. Se o mapa estiver vazio, ainda não há nada desenhado: comece no Desenhador do local."] },
    { target: "ov-side", placement: "left",
      t: ["Alarms, needs attention and quick actions", "Alarmas, atención necesaria y acciones rápidas", "Alarme, Handlungsbedarf und Schnellzugriffe", "Alarmes, à surveiller et actions rapides", "Allarmi, da controllare e azioni rapide", "アラーム・要対応・クイック操作", "报警、待处理和快捷操作", "Alarmes, requer atenção e ações rápidas"],
      b: ["Three cards. Alarms lists the ones waiting, with a tick when all is clear. \"Needs attention\" lists what asks for a person: silent nodes, silent panels, cameras that stopped answering and devices in trouble; each line opens its menu. \"Quick actions\" jumps to the cameras, the form to add a device, the designer and the automations. Start every visit here.",
        "Tres tarjetas. Alarmas lista las que esperan, con una marca cuando todo está tranquilo. \"Requiere atención\" lista lo que pide a una persona: nodos en silencio, centrales en silencio, cámaras que dejaron de responder y dispositivos con problemas; cada línea abre su menú. \"Acciones rápidas\" salta a las cámaras, al formulario para añadir un dispositivo, al diseñador y a las automatizaciones. Empieza cada visita aquí.",
        "Drei Karten. Alarme listet die wartenden, mit einem Haken, wenn alles ruhig ist. \"Handlungsbedarf\" nennt, was einen Menschen braucht: stumme Knoten, stumme Zentralen, Kameras ohne Antwort und Geräte mit Problemen; jede Zeile öffnet ihr Menü. \"Schnellzugriffe\" springen zu den Kameras, zum Formular für ein neues Gerät, zum Designer und zu den Automationen. Beginnen Sie jeden Besuch hier.",
        "Trois cartes. Alarmes liste celles qui attendent, avec une coche quand tout est calme. « À surveiller » liste ce qui demande quelqu'un : nœuds muets, centrales muettes, caméras qui ne répondent plus et appareils en difficulté ; chaque ligne ouvre son menu. « Actions rapides » mène aux caméras, au formulaire d'ajout d'appareil, au concepteur et aux automatisations. Commencez chaque visite ici.",
        "Tre schede. Allarmi elenca quelli in attesa, con una spunta quando è tutto calmo. \"Da controllare\" elenca ciò che chiede una persona: nodi muti, centrali mute, telecamere che non rispondono e dispositivi in difficoltà; ogni riga apre il suo menu. \"Azioni rapide\" porta alle telecamere, al modulo per aggiungere un dispositivo, al progettista e alle automazioni. Inizia ogni visita da qui.",
        "3枚のカード。アラームは未対応の一覧で、問題がなければチェックマークが出ます。「要対応」は人の手が要るもの（応答しないノードや制御盤、停止したカメラ、問題のあるデバイス）を挙げ、各行から該当メニューへ移動できます。「クイック操作」はカメラ、デバイス追加フォーム、設計画面、オートメーションへのショートカット。毎回ここから始めましょう。",
        "三张卡片。“报警”列出待处理的报警，一切正常时显示对勾。“待处理”列出需要人工介入的事项：沉默的节点和主机、停止响应的摄像头和有问题的设备，每行都可打开对应菜单。“快捷操作”直达摄像头、添加设备表单、设计器和自动化。每次登录先看这里。",
        "Três cartões. Alarmes lista os que aguardam, com um visto quando está tudo calmo. \"Requer atenção\" lista o que pede uma pessoa: nós em silêncio, centrais em silêncio, câmaras que deixaram de responder e dispositivos com problemas; cada linha abre o seu menu. \"Ações rápidas\" salta para as câmaras, para o formulário de novo dispositivo, para o desenhador e para as automatizações. Comece cada visita aqui."] },
    { target: "ov-feed", placement: "top",
      t: ["Recent activity", "Actividad reciente", "Letzte Aktivität", "Activité récente", "Attività recente", "最近のアクティビティ", "最近活动", "Atividade recente"],
      b: ["The latest events, newest first, each with how long ago it happened: nodes and cameras going online or offline, alarms raised and cleared, mode changes. It answers \"what just happened?\" without leaving the first screen. \"Open history\" shows the whole story with filters and search, also of alarms you already acknowledged.",
        "Los últimos eventos, el más nuevo primero, cada uno con el tiempo que hace: nodos y cámaras que se conectan o se pierden, alarmas levantadas y cerradas, cambios de modo. Responde a \"¿qué acaba de pasar?\" sin salir de la primera pantalla. \"Abrir el historial\" muestra toda la historia con filtros y búsqueda, también de las alarmas ya reconocidas.",
        "Die letzten Ereignisse, das neueste zuerst, jeweils mit der vergangenen Zeit: Knoten und Kameras, die online oder offline gehen, ausgelöste und beendete Alarme, Moduswechsel. Es beantwortet \"Was ist gerade passiert?\", ohne die erste Seite zu verlassen. \"Verlauf öffnen\" zeigt die ganze Geschichte mit Filtern und Suche, auch von bereits quittierten Alarmen.",
        "Les derniers événements, le plus récent d'abord, chacun avec le temps écoulé : nœuds et caméras qui se connectent ou se perdent, alarmes levées et closes, changements de mode. Cela répond à « que vient-il de se passer ? » sans quitter le premier écran. « Ouvrir l'historique » montre toute l'histoire avec filtres et recherche, y compris les alarmes déjà acquittées.",
        "Gli ultimi eventi, il più recente per primo, ciascuno con il tempo trascorso: nodi e telecamere che si collegano o si perdono, allarmi sollevati e chiusi, cambi di modalità. Risponde a \"cosa è appena successo?\" senza lasciare la prima schermata. \"Apri la cronologia\" mostra tutta la storia con filtri e ricerca, anche degli allarmi già riconosciuti.",
        "最新のイベントを新しい順に、経過時間付きで表示します。ノードやカメラのオンライン／オフライン、アラームの発生と解消、モード変更など。最初の画面を離れずに「いま何が起きたか」が分かります。「履歴を開く」では、確認済みのアラームも含めフィルターと検索付きで全経緯を見られます。",
        "按时间倒序显示最新事件，并标明发生于多久之前：节点和摄像头上线或离线、报警触发与解除、模式切换。不离开首页就能回答“刚才发生了什么”。“打开历史”可用筛选和搜索查看全部经过，包括已确认的报警。",
        "Os últimos eventos, o mais recente primeiro, cada um com o tempo decorrido: nós e câmaras que ficam ligados ou se perdem, alarmes levantados e encerrados, mudanças de modo. Responde a \"o que acabou de acontecer?\" sem sair do primeiro ecrã. \"Abrir o histórico\" mostra toda a história com filtros e pesquisa, também dos alarmes já reconhecidos."] },
  ],
  weather: [
    { target: "wx-consent", placement: "bottom",
      t: ["Turn it on and choose the place", "Actívalo y elige el lugar", "Einschalten und den Ort wählen", "Activez-la et choisissez le lieu", "Attivalo e scegli il luogo", "有効にして場所を選ぶ", "开启并选择地点", "Ative e escolha o local"],
      b: ["The first time, the weather is off. Turn it on and either search a town or city by name or type the latitude and longitude yourself, then pick the result. The place is kept in the server, so every browser sees the same. Only the place you choose is sent to the public weather services: nothing from your cameras or sensors.",
        "La primera vez, el tiempo está desactivado. Actívalo y busca una localidad por nombre o escribe tú mismo la latitud y la longitud; luego elige el resultado. El lugar se guarda en el servidor, así que todos los navegadores ven lo mismo. A los servicios públicos del tiempo solo se envía el lugar que eliges: nada de tus cámaras ni sensores.",
        "Beim ersten Mal ist das Wetter aus. Schalten Sie es ein und suchen Sie einen Ort per Namen oder geben Sie Breiten- und Längengrad selbst ein, dann wählen Sie das Ergebnis. Der Ort wird im Server gespeichert, sodass jeder Browser dasselbe sieht. An die öffentlichen Wetterdienste geht nur der gewählte Ort: nichts von Ihren Kameras oder Sensoren.",
        "La première fois, la météo est désactivée. Activez-la, puis cherchez une commune par son nom ou saisissez vous-même latitude et longitude, et choisissez le résultat. Le lieu est conservé sur le serveur, donc tous les navigateurs voient la même chose. Seul le lieu choisi est envoyé aux services météo publics : rien de vos caméras ni de vos capteurs.",
        "La prima volta il meteo è spento. Attivalo e cerca una località per nome oppure scrivi tu latitudine e longitudine, poi scegli il risultato. Il luogo è salvato nel server, quindi ogni browser vede lo stesso. Ai servizi meteo pubblici va solo il luogo scelto: nulla delle tue telecamere o dei tuoi sensori.",
        "初回は天気がオフです。有効にして、町や都市名で検索するか緯度・経度を自分で入力し、結果を選びます。場所はサーバーに保存されるので、どのブラウザーでも同じです。公開の気象サービスに送られるのは選んだ場所だけで、カメラやセンサーの情報は送られません。",
        "首次使用时天气功能是关闭的。开启后可按名称搜索城镇，或自己输入纬度和经度，然后选择结果。地点保存在服务器上，因此所有浏览器看到的都一样。只有你选的地点会发送给公共天气服务，摄像头和传感器的任何数据都不会发送。",
        "Na primeira vez, o tempo está desligado. Ative-o e procure uma localidade pelo nome ou escreva você a latitude e a longitude, e escolha o resultado. O local fica guardado no servidor, por isso todos os navegadores veem o mesmo. Aos serviços públicos de meteorologia só vai o local escolhido: nada das suas câmaras ou sensores."] },
    { target: "wx-bar", placement: "bottom",
      t: ["The place and its actions", "El lugar y sus acciones", "Der Ort und seine Aktionen", "Le lieu et ses actions", "Il luogo e le sue azioni", "場所と操作", "地点及其操作", "O local e as suas ações"],
      b: ["The bar shows the chosen place with its coordinates and height. \"Change place\" opens the search again to pick another; \"Turn off and forget the place\" removes it from the server. If the forecast does not load, check the connection of the server to the internet in the Network menu: the weather is read from outside.",
        "La barra muestra el lugar elegido con sus coordenadas y altitud. \"Cambiar lugar\" abre de nuevo la búsqueda para elegir otro; \"Desactivar y olvidar el lugar\" lo borra del servidor. Si la previsión no carga, mira la conexión del servidor a internet en el menú Red: el tiempo se lee de fuera.",
        "Die Leiste zeigt den gewählten Ort mit Koordinaten und Höhe. \"Ort ändern\" öffnet die Suche erneut; \"Ausschalten und Ort vergessen\" löscht ihn im Server. Lädt die Vorhersage nicht, prüfen Sie im Menü Netz die Internetverbindung des Servers: das Wetter wird von außen gelesen.",
        "La barre montre le lieu choisi avec ses coordonnées et son altitude. « Changer de lieu » rouvre la recherche pour en choisir un autre ; « Désactiver et oublier le lieu » l'efface du serveur. Si les prévisions ne se chargent pas, vérifiez la connexion du serveur à Internet dans le menu Réseau : la météo est lue à l'extérieur.",
        "La barra mostra il luogo scelto con coordinate e altitudine. \"Cambia luogo\" riapre la ricerca per sceglierne un altro; \"Disattiva e dimentica il luogo\" lo cancella dal server. Se le previsioni non si caricano, controlla la connessione del server a internet nel menu Rete: il meteo viene letto dall'esterno.",
        "バーには選んだ場所の座標と標高が出ます。「場所を変更」で再検索し、「オフにして場所を忘れる」でサーバーから削除します。予報が読み込まれないときは、ネットワークメニューでサーバーのインターネット接続を確認してください。天気は外部から取得しています。",
        "栏中显示所选地点及其坐标和海拔。“更换地点”重新打开搜索以选择别处；“关闭并忘记地点”会从服务器删除它。如果预报加载不出来，请在“网络”菜单检查服务器的互联网连接：天气数据来自外部。",
        "A barra mostra o local escolhido com as coordenadas e a altitude. \"Mudar de local\" volta a abrir a pesquisa para escolher outro; \"Desligar e esquecer o local\" apaga-o do servidor. Se a previsão não carregar, verifique a ligação do servidor à internet no menu Rede: o tempo é lido do exterior."] },
    { target: "wx-hero", placement: "bottom",
      t: ["Now, the next hours and the days", "Ahora, las próximas horas y los días", "Jetzt, die nächsten Stunden und die Tage", "Maintenant, les prochaines heures et les jours", "Adesso, le prossime ore e i giorni", "現在・数時間先・数日先", "当前、未来几小时和几天", "Agora, as próximas horas e os dias"],
      b: ["The big card is the weather now: temperature, how it feels, wind, humidity, pressure, rain and cloud, with sunrise and sunset. Below come the next 48 hours hour by hour and the daily forecast with the highest and lowest. Warnings from the forecast appear on top when there are any. Use it to decide if the garden sensors or the solar production will be affected.",
        "La tarjeta grande es el tiempo ahora: temperatura, sensación, viento, humedad, presión, lluvia y nubes, con la salida y la puesta del sol. Debajo vienen las próximas 48 horas hora a hora y la previsión de los días con máxima y mínima. Los avisos de la previsión salen arriba si los hay. Sirve para decidir si afectará a los sensores del jardín o a la producción solar.",
        "Die große Karte ist das Wetter jetzt: Temperatur, gefühlte Temperatur, Wind, Feuchte, Druck, Regen und Wolken, mit Sonnenauf- und -untergang. Darunter die nächsten 48 Stunden Stunde für Stunde und die Tagesvorhersage mit Höchst- und Tiefstwerten. Warnungen der Vorhersage erscheinen oben. So lässt sich abschätzen, ob Gartensensoren oder Solarertrag betroffen sind.",
        "La grande carte donne la météo actuelle : température, ressenti, vent, humidité, pression, pluie et nuages, avec lever et coucher du soleil. Dessous, les 48 prochaines heures heure par heure et les prévisions des jours avec maximale et minimale. Les avertissements de la prévision s'affichent en haut s'il y en a. Utile pour savoir si les capteurs du jardin ou la production solaire seront touchés.",
        "La scheda grande è il meteo adesso: temperatura, percepita, vento, umidità, pressione, pioggia e nuvole, con alba e tramonto. Sotto le prossime 48 ore ora per ora e le previsioni dei giorni con massima e minima. Gli avvisi della previsione compaiono in alto, se ci sono. Serve a capire se i sensori del giardino o la produzione solare saranno toccati.",
        "大きなカードが現在の天気です。気温、体感、風、湿度、気圧、雨量、雲量と日の出・日の入り。その下に48時間の1時間ごとの予報と、日ごとの最高・最低気温があります。予報の警報があれば上部に表示されます。庭のセンサーや太陽光発電への影響を判断するのに役立ちます。",
        "大卡片显示当前天气：气温、体感温度、风、湿度、气压、降雨和云量，以及日出日落。下方是未来48小时的逐小时预报和每日最高最低温。若有预报预警会显示在顶部。可据此判断花园传感器或太阳能发电是否会受影响。",
        "O cartão grande é o tempo agora: temperatura, sensação térmica, vento, humidade, pressão, chuva e nuvens, com o nascer e o pôr do sol. Por baixo, as próximas 48 horas hora a hora e a previsão dos dias com máxima e mínima. Os avisos da previsão aparecem em cima, se os houver. Serve para decidir se afetará os sensores do jardim ou a produção solar."] },
    { target: "wx-radar", placement: "top",
      t: ["Rain radar and air quality", "Radar de lluvia y calidad del aire", "Regenradar und Luftqualität", "Radar de pluie et qualité de l'air", "Radar della pioggia e qualità dell'aria", "雨雲レーダーと空気質", "降雨雷达与空气质量", "Radar de chuva e qualidade do ar"],
      b: ["The radar plays the last frames of rain (and, if you choose, of clouds from the satellite) over a map. Play and Pause control the animation, the opacity slider lets you see the map below and \"Center on my place\" recentres the view. Further down, the air quality card gives the index, the pollutants and, when available, the pollen. Tip: pause on the frame that shows the rain closest to your place.",
        "El radar reproduce los últimos fotogramas de lluvia (y, si quieres, de nubes por satélite) sobre un mapa. Reproducir y Pausa controlan la animación, el deslizador de opacidad deja ver el mapa de debajo y \"Centrar en mi lugar\" recentra la vista. Más abajo, la tarjeta de calidad del aire da el índice, los contaminantes y, si hay, el polen. Consejo: pausa en el fotograma que muestre la lluvia más cerca de tu lugar.",
        "Das Radar spielt die letzten Regenbilder (und auf Wunsch Wolken vom Satelliten) über einer Karte ab. Abspielen und Pause steuern die Animation, der Deckkraft-Regler lässt die Karte darunter sehen, und \"Auf meinen Ort zentrieren\" zentriert die Ansicht. Weiter unten zeigt die Luftqualität den Index, die Schadstoffe und, falls vorhanden, den Pollen. Tipp: Pausieren Sie auf dem Bild, auf dem der Regen Ihrem Ort am nächsten ist.",
        "Le radar rejoue les dernières images de pluie (et, si vous voulez, des nuages par satellite) sur une carte. Lecture et Pause pilotent l'animation, le curseur d'opacité laisse voir la carte dessous et « Centrer sur mon lieu » recentre la vue. Plus bas, la carte de qualité de l'air donne l'indice, les polluants et, s'il y en a, le pollen. Astuce : mettez en pause sur l'image où la pluie est la plus proche de votre lieu.",
        "Il radar riproduce gli ultimi fotogrammi di pioggia (e, se vuoi, delle nuvole da satellite) su una mappa. Riproduci e Pausa controllano l'animazione, il cursore dell'opacità lascia vedere la mappa sotto e \"Centra sul mio luogo\" ricentra la vista. Più sotto, la scheda della qualità dell'aria dà l'indice, gli inquinanti e, se c'è, il polline. Consiglio: metti in pausa sul fotogramma con la pioggia più vicina al tuo luogo.",
        "レーダーは直近の雨雲（希望すれば衛星の雲も）を地図上でアニメーション再生します。再生／一時停止でアニメを操作し、不透明度スライダーで下の地図を透かし、「現在地を中心に」で表示を戻します。その下の空気質カードには指数、汚染物質、花粉（取得できる場合）が出ます。ヒント：雨雲が自宅に最も近いコマで一時停止すると見やすいです。",
        "雷达在地图上回放最近几帧降雨（也可选择卫星云图）。播放和暂停控制动画，透明度滑块可透出下方地图，“以我的地点为中心”可重新居中。再往下的空气质量卡片给出指数、污染物，有数据时还有花粉。提示：在降雨最接近你所在地点的那一帧暂停。",
        "O radar reproduz as últimas imagens de chuva (e, se quiser, de nuvens por satélite) sobre um mapa. Reproduzir e Pausa controlam a animação, o cursor de opacidade deixa ver o mapa por baixo e \"Centrar no meu local\" recentra a vista. Mais abaixo, o cartão da qualidade do ar dá o índice, os poluentes e, quando existir, o pólen. Dica: pause na imagem em que a chuva está mais perto do seu local."] },
  ],
  alarms: [
    { target: "al-actions", placement: "bottom",
      t: ["Arm, disarm and acknowledge all", "Armar, desarmar y reconocer todas", "Scharf, unscharf und alle quittieren", "Armer, désarmer et tout acquitter", "Inserire, disinserire e riconoscere tutti", "警戒・解除・すべて確認", "布防、撤防与全部确认", "Armar, desarmar e reconhecer tudo"],
      b: ["The big button arms or disarms the system, with the same check before arming as in Overview; disarming asks for your PIN. \"Acknowledge all\" appears while alarms are waiting and marks every one as seen in one click. Mistake to avoid: acknowledging all without reading them. Acknowledging means \"I have seen it\", not \"it is solved\".",
        "El botón grande arma o desarma el sistema, con la misma comprobación previa que en Resumen; desarmar pide tu PIN. \"Reconocer todas\" aparece mientras hay alarmas esperando y marca todas como vistas de un clic. Error que evitar: reconocer todas sin leerlas. Reconocer significa \"la he visto\", no \"está resuelta\".",
        "Der große Knopf schaltet das System scharf oder unscharf, mit derselben Prüfung wie in der Übersicht; Unscharfschalten verlangt Ihre PIN. \"Alle quittieren\" erscheint, solange Alarme warten, und markiert alle mit einem Klick als gesehen. Zu vermeiden: alle quittieren, ohne sie zu lesen. Quittieren heißt \"gesehen\", nicht \"gelöst\".",
        "Le gros bouton arme ou désarme le système, avec la même vérification qu'en Aperçu ; désarmer demande votre PIN. « Tout acquitter » apparaît tant que des alarmes attendent et marque toutes comme vues d'un clic. À éviter : tout acquitter sans les lire. Acquitter veut dire « je l'ai vue », pas « c'est réglé ».",
        "Il grande pulsante inserisce o disinserisce il sistema, con lo stesso controllo prima di inserire che in Panoramica; disinserire chiede il PIN. \"Riconosci tutti\" appare finché ci sono allarmi in attesa e li segna tutti come visti con un clic. Da evitare: riconoscerli tutti senza leggerli. Riconoscere significa \"l'ho visto\", non \"è risolto\".",
        "大きなボタンで警戒／解除を切り替えます（警戒前の点検は概要と同じ、解除にはPIN）。未対応のアラームがあると「すべて確認」が表示され、1回でまとめて確認済みにできます。避けたい間違いは、読まずに全部確認すること。確認は「見た」という意味で、「解決した」ではありません。",
        "大按钮用于布防或撤防，布防前的检查与“概览”相同；撤防需要 PIN。有报警待处理时会出现“全部确认”，一键把所有报警标为已看。要避免的错误：没读就全部确认。确认的意思是“我看到了”，不是“已解决”。",
        "O botão grande arma ou desarma o sistema, com a mesma verificação prévia que em Resumo; desarmar pede o PIN. \"Reconhecer tudo\" aparece enquanto há alarmes à espera e marca todos como vistos com um clique. Erro a evitar: reconhecer tudo sem ler. Reconhecer significa \"já vi\", não \"está resolvido\"."] },
    { target: "al-toolbar", placement: "bottom",
      t: ["Filters and search", "Filtros y búsqueda", "Filter und Suche", "Filtres et recherche", "Filtri e ricerca", "フィルターと検索", "筛选与搜索", "Filtros e pesquisa"],
      b: ["Narrow the list by severity (critical, high, warning) and by source (radar, camera, device, alarm panel, network, solar, electrical...), or type any text in the search box: a node name, a device, a code. The counter shows how many are visible out of the total. If the list looks empty but the counter says otherwise, a filter is still on: set both to All.",
        "Reduce la lista por gravedad (crítica, alta, aviso) y por origen (radar, cámara, dispositivo, central, red, solar, eléctrico...), o escribe cualquier texto en el buscador: un nombre de nodo, un dispositivo, un código. El contador muestra cuántas se ven del total. Si la lista parece vacía pero el contador dice otra cosa, queda un filtro puesto: pon ambos en Todas.",
        "Grenzen Sie die Liste nach Schweregrad (kritisch, hoch, Warnung) und Quelle (Radar, Kamera, Gerät, Alarmzentrale, Netz, Solar, Elektrik...) ein, oder tippen Sie einen Text in die Suche: einen Knotennamen, ein Gerät, einen Code. Der Zähler zeigt, wie viele von allen sichtbar sind. Wirkt die Liste leer, der Zähler sagt aber etwas anderes, ist noch ein Filter aktiv: beide auf Alle stellen.",
        "Réduisez la liste par gravité (critique, élevée, avertissement) et par source (radar, caméra, appareil, centrale, réseau, solaire, électrique...), ou tapez un texte dans la recherche : un nom de nœud, un appareil, un code. Le compteur indique combien sont visibles sur le total. Si la liste semble vide alors que le compteur dit autre chose, un filtre est encore actif : mettez les deux sur Tout.",
        "Riduci l'elenco per gravità (critica, alta, avviso) e per origine (radar, telecamera, dispositivo, centrale, rete, solare, elettrico...), oppure scrivi un testo nella ricerca: il nome di un nodo, un dispositivo, un codice. Il contatore mostra quanti se ne vedono sul totale. Se l'elenco sembra vuoto ma il contatore dice altro, resta un filtro attivo: metti entrambi su Tutti.",
        "重大度（重大・高・警告）と発生源（レーダー、カメラ、デバイス、制御盤、ネットワーク、太陽光、電気など）で絞り込めます。検索欄にはノード名、デバイス、コードなど任意の文字を入力できます。カウンターは全体のうち表示中の件数です。一覧が空なのにカウンターが違う場合はフィルターが残っています。両方を「すべて」に戻してください。",
        "可按严重程度（严重、高、警告）和来源（雷达、摄像头、设备、报警主机、网络、太阳能、电气等）缩小列表，也可在搜索框输入任意文字：节点名、设备、代码。计数器显示可见数量和总数。如果列表看似为空但计数器不一致，说明仍有筛选条件：把两项都设为“全部”。",
        "Reduza a lista por gravidade (crítica, alta, aviso) e por origem (radar, câmara, dispositivo, central, rede, solar, elétrico...), ou escreva qualquer texto na pesquisa: o nome de um nó, um dispositivo, um código. O contador mostra quantos se veem do total. Se a lista parecer vazia mas o contador disser outra coisa, ainda há um filtro ativo: ponha ambos em Todas."] },
    { target: "al-list", placement: "top",
      t: ["One card per alarm", "Una tarjeta por alarma", "Eine Karte pro Alarm", "Une carte par alarme", "Una scheda per allarme", "アラーム1件につき1枚", "每条报警一张卡片", "Um cartão por alarme"],
      b: ["Each card has the severity, what happened, where it comes from (the device, camera or node by name), its state and how long ago. Acknowledge marks it as seen; Details shows the facts (address, MAC, port, numbers); \"Mark the device as known\" welcomes a new network device so it stops alarming; the cross deletes it. A viewer account only looks and cannot do any of this.",
        "Cada tarjeta lleva la gravedad, lo que ocurrió, de dónde viene (el dispositivo, cámara o nodo por su nombre), su estado y hace cuánto. Reconocer la marca como vista; Detalles muestra los datos (dirección, MAC, puerto, cifras); \"Marcar el dispositivo como conocido\" da la bienvenida a un dispositivo nuevo de la red para que deje de alarmar; la cruz la borra. Una cuenta de observador solo mira y no puede hacer nada de esto.",
        "Jede Karte zeigt Schweregrad, was geschah, woher es kommt (Gerät, Kamera oder Knoten mit Namen), Zustand und Zeitpunkt. Quittieren markiert sie als gesehen; Details zeigt die Fakten (Adresse, MAC, Port, Zahlen); \"Gerät als bekannt markieren\" heißt ein neues Netzwerkgerät willkommen, damit es nicht mehr alarmiert; das Kreuz löscht. Ein Betrachter-Konto kann nur ansehen.",
        "Chaque carte porte la gravité, ce qui s'est passé, d'où cela vient (l'appareil, la caméra ou le nœud par son nom), son état et depuis quand. Acquitter la marque comme vue ; Détails montre les faits (adresse, MAC, port, chiffres) ; « Marquer l'appareil comme connu » accueille un nouvel appareil du réseau pour qu'il n'alarme plus ; la croix la supprime. Un compte lecteur ne peut que regarder.",
        "Ogni scheda riporta la gravità, cosa è successo, da dove viene (il dispositivo, la telecamera o il nodo per nome), lo stato e da quanto. Riconosci la segna come vista; Dettagli mostra i dati (indirizzo, MAC, porta, numeri); \"Segna il dispositivo come noto\" dà il benvenuto a un nuovo dispositivo di rete perché smetta di allarmare; la croce la elimina. Un account osservatore può solo guardare.",
        "各カードには重大度、内容、発生源（デバイス・カメラ・ノードの名前）、状態、経過時間があります。「確認」で確認済み、「詳細」で事実（アドレス、MAC、ポート、数値）を表示、「既知のデバイスにする」で新しいネットワーク機器を許可して警報を止め、×で削除します。閲覧者アカウントは見るだけでこれらの操作はできません。",
        "每张卡片包含严重程度、发生了什么、来源（设备、摄像头或节点的名称）、状态以及发生时间。“确认”标记为已看；“详情”显示事实（地址、MAC、端口、数值）；“标记设备为已知”可接纳新的网络设备使其不再报警；叉号用于删除。查看者账户只能查看，不能进行这些操作。",
        "Cada cartão traz a gravidade, o que aconteceu, de onde vem (o dispositivo, câmara ou nó pelo nome), o estado e há quanto tempo. Reconhecer marca-o como visto; Detalhes mostra os dados (endereço, MAC, porta, números); \"Marcar o dispositivo como conhecido\" dá as boas-vindas a um novo dispositivo da rede para deixar de alarmar; a cruz apaga-o. Uma conta de observador só olha."] },
    { target: "al-record", placement: "top",
      t: ["The record of what you acknowledged", "El registro de lo reconocido", "Das Protokoll des Quittierten", "Le registre de ce qui est acquitté", "Il registro di ciò che hai riconosciuto", "確認済みの記録", "已确认报警的记录", "O registo do que reconheceu"],
      b: ["An acknowledged alarm leaves the active list and stays here, whether its cause has ended or not. If the cause is still going on, the same condition reported again does not bring it back: it returns only after the cause ends and happens again. \"Clear the record\" empties this list (it asks first) but not History, where the whole story stays.",
        "Una alarma reconocida sale de la lista activa y se queda aquí, haya terminado su causa o no. Si la causa sigue, la misma condición informada otra vez no la hace volver: vuelve solo cuando la causa termina y se repite. \"Vaciar el registro\" vacía esta lista (pregunta antes) pero no el Historial, donde queda toda la historia.",
        "Ein quittierter Alarm verlässt die aktive Liste und bleibt hier, ob seine Ursache beendet ist oder nicht. Dauert die Ursache an, bringt dieselbe erneut gemeldete Bedingung ihn nicht zurück: Er kommt erst wieder, wenn die Ursache endet und neu auftritt. \"Protokoll leeren\" leert diese Liste (mit Rückfrage), nicht den Verlauf, wo die ganze Geschichte bleibt.",
        "Une alarme acquittée quitte la liste active et reste ici, que sa cause ait cessé ou non. Si la cause continue, la même condition rapportée à nouveau ne la ramène pas : elle revient seulement quand la cause cesse puis se reproduit. « Vider le registre » vide cette liste (avec confirmation) mais pas l'Historique, où toute l'histoire reste.",
        "Un allarme riconosciuto lascia l'elenco attivo e resta qui, sia che la causa sia finita o no. Se la causa continua, la stessa condizione riportata di nuovo non lo fa tornare: torna solo dopo che la causa finisce e si ripete. \"Svuota il registro\" svuota questo elenco (chiede prima) ma non la Cronologia, dove resta tutta la storia.",
        "確認済みのアラームは有効な一覧から外れてここに残ります（原因が続いていても同様）。原因が続いている間に同じ状態が再報告されても戻りません。原因が解消して再び起きたときだけ戻ります。「記録を消去」はこの一覧を空にします（確認あり）が、全経緯が残る履歴には影響しません。",
        "已确认的报警会从活动列表移到这里，无论原因是否已消除。如果原因仍在持续，相同的状况再次上报不会让它回来；只有原因消除后再次发生才会重新出现。“清空记录”会清空此列表（会先询问），但不影响“历史”，完整经过仍保留在那里。",
        "Um alarme reconhecido sai da lista ativa e fica aqui, tenha a causa terminado ou não. Se a causa continua, a mesma condição comunicada de novo não o faz voltar: só volta depois de a causa acabar e se repetir. \"Limpar o registo\" esvazia esta lista (pergunta antes), mas não o Histórico, onde fica toda a história."] },
    { target: "stage", placement: "left",
      t: ["How an alarm reaches you", "Cómo te llega una alarma", "Wie ein Alarm Sie erreicht", "Comment une alarme vous parvient", "Come ti arriva un allarme", "アラームの届き方", "报警如何通知到你", "Como um alarme chega até si"],
      b: ["A new alarm appears as a pop-up that never blocks the page, with an Acknowledge button and a jump to the right menu. A critical one also sounds, and with the browser's permission it shows as a notification even when Studio is on another tab. The alarms already on the list when you opened Studio are not announced again. Sounds, voice and pop-ups are chosen in Configuration > Preferences.",
        "Una alarma nueva aparece como aviso emergente que nunca bloquea la página, con un botón Reconocer y un salto al menú correcto. Una crítica además suena, y con permiso del navegador sale como notificación aunque Studio esté en otra pestaña. Las alarmas que ya estaban en la lista al abrir Studio no se anuncian otra vez. Los sonidos, la voz y los avisos se eligen en Configuración > Preferencias.",
        "Ein neuer Alarm erscheint als Pop-up, das die Seite nie blockiert, mit einem Quittieren-Knopf und einem Sprung ins richtige Menü. Ein kritischer ertönt außerdem und erscheint mit Erlaubnis des Browsers als Benachrichtigung, auch wenn Studio in einem anderen Tab ist. Alarme, die beim Öffnen von Studio schon in der Liste standen, werden nicht erneut angesagt. Töne, Stimme und Pop-ups wählen Sie unter Konfiguration > Einstellungen.",
        "Une nouvelle alarme apparaît dans une fenêtre qui ne bloque jamais la page, avec un bouton Acquitter et un saut vers le bon menu. Une alarme critique sonne aussi et, avec l'autorisation du navigateur, s'affiche en notification même si Studio est dans un autre onglet. Les alarmes déjà dans la liste à l'ouverture de Studio ne sont pas annoncées de nouveau. Sons, voix et fenêtres se choisissent dans Configuration > Préférences.",
        "Un nuovo allarme appare come finestra che non blocca mai la pagina, con un pulsante Riconosci e un salto al menu giusto. Uno critico suona anche e, con il permesso del browser, compare come notifica pur con Studio in un'altra scheda. Gli allarmi già presenti all'apertura di Studio non vengono annunciati di nuovo. Suoni, voce e finestre si scelgono in Configurazione > Preferenze.",
        "新しいアラームはページを妨げないポップアップで表示され、「確認」ボタンと該当メニューへのジャンプが付きます。重大なものは音も鳴り、ブラウザーの許可があれば別のタブでも通知として表示されます。Studioを開いた時点で一覧にあったアラームは再通知されません。音・音声・ポップアップは「設定 > 環境設定」で選びます。",
        "新报警会以不会阻挡页面的弹窗出现，带有“确认”按钮和跳转到对应菜单的链接。严重报警还会发声，并在浏览器允许时以通知形式显示，即使 Studio 在其他标签页。打开 Studio 时列表中已有的报警不会再次播报。声音、语音和弹窗在“配置 > 偏好设置”中选择。",
        "Um alarme novo aparece como aviso que nunca bloqueia a página, com um botão Reconhecer e um salto para o menu certo. Um crítico também soa e, com permissão do navegador, aparece como notificação mesmo com o Studio noutro separador. Os alarmes que já estavam na lista ao abrir o Studio não são anunciados outra vez. Sons, voz e avisos escolhem-se em Configuração > Preferências."] },
  ],
  alarmPanels: [
    { target: "ap-head", placement: "bottom",
      t: ["The totals of your panels", "Los totales de tus centrales", "Die Summen Ihrer Zentralen", "Les totaux de vos centrales", "I totali delle tue centrali", "制御盤の合計", "主机汇总", "Os totais das suas centrais"],
      b: ["The tiles count the alarm nodes that answer out of the total, how many are armed and how many are sounding. A panel that stops reporting becomes \"silent\" and raises an alarm. These panels are the ARMOR-ALARM nodes: each one reads its wired zones, listens to its Zigbee sensors and runs the arming, the delays, the siren and the PIN by itself, with or without the server.",
        "Las fichas cuentan los nodos de alarma que responden sobre el total, cuántos están armados y cuántos suenan. Una central que deja de informar pasa a \"silenciosa\" y levanta una alarma. Estas centrales son los nodos ARMOR-ALARM: cada uno lee sus zonas cableadas, escucha sus sensores Zigbee y gestiona el armado, los retardos, la sirena y el PIN por sí mismo, con servidor o sin él.",
        "Die Kacheln zählen die antwortenden Alarmknoten von allen, wie viele scharf sind und wie viele heulen. Eine Zentrale, die nicht mehr berichtet, wird \"stumm\" und löst einen Alarm aus. Diese Zentralen sind die ARMOR-ALARM-Knoten: jeder liest seine verdrahteten Zonen, hört seine Zigbee-Sensoren und steuert Scharfschaltung, Verzögerungen, Sirene und PIN selbst, mit oder ohne Server.",
        "Les tuiles comptent les nœuds d'alarme qui répondent sur le total, combien sont armés et combien sonnent. Une centrale qui cesse de rapporter devient « muette » et lève une alarme. Ces centrales sont les nœuds ARMOR-ALARM : chacun lit ses zones filaires, écoute ses capteurs Zigbee et gère seul l'armement, les temporisations, la sirène et le PIN, avec ou sans serveur.",
        "Le schede contano i nodi di allarme che rispondono sul totale, quanti sono inseriti e quanti suonano. Una centrale che smette di riferire diventa \"muta\" e solleva un allarme. Queste centrali sono i nodi ARMOR-ALARM: ognuno legge le sue zone cablate, ascolta i suoi sensori Zigbee e gestisce da solo inserimento, ritardi, sirena e PIN, con o senza server.",
        "タイルは、応答しているアラームノード数（全体比）、警戒中の数、鳴動中の数を示します。報告が止まった制御盤は「無通信」になりアラームが上がります。これらの制御盤は ARMOR-ALARM ノードで、配線ゾーンの読み取り、Zigbeeセンサーの受信、警戒・遅延・サイレン・PINの管理を、サーバーの有無にかかわらず自分で行います。",
        "卡片统计响应的报警节点数（占总数）、已布防数量和正在鸣响的数量。停止上报的主机会变为“沉默”并触发报警。这些主机就是 ARMOR-ALARM 节点：每个节点自己读取有线分区、监听 Zigbee 传感器，并独立管理布防、延时、警笛和 PIN，无论有无服务器。",
        "Os cartões contam os nós de alarme que respondem do total, quantos estão armados e quantos estão a tocar. Uma central que deixa de comunicar fica \"silenciosa\" e levanta um alarme. Estas centrais são os nós ARMOR-ALARM: cada um lê as suas zonas com fios, escuta os seus sensores Zigbee e trata sozinho do armar, dos atrasos, da sirene e do PIN, com ou sem servidor."] },
    { target: "ap-card", placement: "left",
      t: ["A panel card: mode, zones and events", "La tarjeta de una central: modo, zonas y eventos", "Die Karte einer Zentrale: Modus, Zonen, Ereignisse", "La carte d'une centrale : mode, zones et événements", "La scheda di una centrale: modalità, zone ed eventi", "制御盤カード：モード・ゾーン・イベント", "主机卡片：模式、分区和事件", "O cartão de uma central: modo, zonas e eventos"],
      b: ["Each card shows whether the node is guarding, its mode (away or at home), every zone (normal, triggered or tampered) and what happened last. A sounding siren raises a critical alarm in Alarms and a zone in tamper a high one. A stale card means the node has not reported lately: check its power and network before suspecting the sensors.",
        "Cada tarjeta muestra si el nodo vigila, su modo (ausente o en casa), cada zona (normal, disparada o sabotaje) y lo último que pasó. Una sirena sonando levanta una alarma crítica en Alarmas y una zona en sabotaje una alta. Una tarjeta apagada significa que el nodo no ha informado hace rato: revisa su alimentación y su red antes de sospechar de los sensores.",
        "Jede Karte zeigt, ob der Knoten überwacht, seinen Modus (abwesend oder zu Hause), jede Zone (normal, ausgelöst oder Sabotage) und das Letzte, was geschah. Eine heulende Sirene löst unter Alarme einen kritischen Alarm aus, eine Zone in Sabotage einen hohen. Eine ausgegraute Karte heißt: Der Knoten hat länger nicht berichtet - prüfen Sie Strom und Netz, bevor Sie die Sensoren verdächtigen.",
        "Chaque carte montre si le nœud surveille, son mode (absent ou à la maison), chaque zone (normale, déclenchée ou sabotage) et le dernier événement. Une sirène qui sonne lève une alarme critique dans Alarmes et une zone en sabotage une alarme élevée. Une carte grisée signifie que le nœud n'a pas rapporté depuis un moment : vérifiez son alimentation et son réseau avant de soupçonner les capteurs.",
        "Ogni scheda mostra se il nodo sorveglia, la sua modalità (fuori o in casa), ogni zona (normale, scattata o manomessa) e l'ultima cosa accaduta. Una sirena che suona solleva un allarme critico in Allarmi e una zona manomessa uno alto. Una scheda spenta significa che il nodo non riferisce da un po': controlla alimentazione e rete prima di sospettare dei sensori.",
        "各カードには、ノードが監視中か、モード（外出／在宅）、各ゾーンの状態（正常・作動・改ざん）、直近の出来事が表示されます。サイレンが鳴ると「アラーム」に重大アラームが、ゾーンの改ざんで高アラームが上がります。カードが灰色なら、しばらく報告がありません。センサーを疑う前に電源とネットワークを確認してください。",
        "每张卡片显示节点是否在守护、其模式（离家或在家）、每个分区（正常、触发或防拆）以及最近发生的事。警笛鸣响会在“报警”中产生严重报警，分区被防拆则产生高级报警。卡片变灰表示节点已有一段时间未上报：先检查供电和网络，再怀疑传感器。",
        "Cada cartão mostra se o nó vigia, o seu modo (ausente ou em casa), cada zona (normal, disparada ou sabotagem) e o último acontecimento. Uma sirene a tocar levanta um alarme crítico em Alarmes e uma zona em sabotagem um alto. Um cartão apagado significa que o nó não comunica há algum tempo: verifique a alimentação e a rede antes de suspeitar dos sensores."] },
    { target: "ap-modes", placement: "bottom",
      t: ["Arming modes", "Modos de armado", "Scharfschaltmodi", "Modes d'armement", "Modalità di inserimento", "警戒モード", "布防模式", "Modos de armar"],
      b: ["Away, Home, Night or your own: each mode says which zones guard, which ones alarm at once or after the entry delay, the exit and entry delays, whether the siren sounds (a silent alarm is still recorded and told) and how loudly the server tells people. An administrator opens \"Edit the modes\" to change them and saves the list as a whole; away and home cannot be removed, and at most eight modes exist. In a panel's card, the Mode picker and its button arm in the chosen mode; a panel whose firmware does not know modes keeps the two buttons. A mode never changes the PIN, the lockout or the smoke, panic and tamper zones, which always guard.",
        "Fuera, En casa, Noche o el tuyo: cada modo dice qué zonas vigilan, cuáles disparan la alarma al instante o tras el retardo de entrada, los retardos de salida y entrada, si suena la sirena (una alarma silenciosa se anota y se avisa igual) y con qué fuerza avisa el servidor. Un administrador abre \"Editar los modos\" para cambiarlos y guarda la lista entera; Fuera y En casa no se pueden quitar y como mucho hay ocho modos. En la tarjeta de una central, el selector de modo y su botón arman en el modo elegido; una central cuyo firmware no conoce los modos conserva los dos botones. Un modo nunca cambia el PIN, el bloqueo ni las zonas de humo, pánico y sabotaje, que siempre vigilan.",
        "Abwesend, Zuhause, Nacht oder Ihr eigener: Jeder Modus legt fest, welche Zonen überwachen, welche sofort oder nach der Eingangsverzögerung alarmieren, die Ausgangs- und Eingangsverzögerung, ob die Sirene ertönt (ein stiller Alarm wird trotzdem protokolliert und gemeldet) und wie nachdrücklich der Server informiert. Ein Administrator öffnet \"Modi bearbeiten\", ändert sie und speichert die ganze Liste; Abwesend und Zuhause lassen sich nicht entfernen, und es gibt höchstens acht Modi. In der Karte einer Zentrale schalten die Modusauswahl und ihre Taste im gewählten Modus scharf; eine Zentrale, deren Firmware keine Modi kennt, behält die zwei Tasten. Ein Modus ändert nie die PIN, die Sperre oder die Rauch-, Panik- und Sabotagezonen, die immer überwachen.",
        "Absent, Présent, Nuit ou le vôtre : chaque mode dit quelles zones surveillent, lesquelles déclenchent l'alarme tout de suite ou après la temporisation d'entrée, les temporisations de sortie et d'entrée, si la sirène sonne (une alarme silencieuse est quand même notée et signalée) et avec quelle insistance le serveur prévient. Un administrateur ouvre « Modifier les modes » pour les changer et enregistre la liste entière ; Absent et Présent ne peuvent pas être retirés et il y a huit modes au plus. Dans la carte d'une centrale, le sélecteur de mode et son bouton arment dans le mode choisi ; une centrale dont le micrologiciel ne connaît pas les modes garde les deux boutons. Un mode ne change jamais le PIN, le verrouillage ni les zones fumée, panique et sabotage, qui surveillent toujours.",
        "Fuori casa, In casa, Notte o la tua: ogni modalità dice quali zone sorvegliano, quali fanno scattare l'allarme subito o dopo il ritardo d'ingresso, i ritardi di uscita e d'ingresso, se la sirena suona (un allarme silenzioso viene comunque registrato e segnalato) e con quanta insistenza il server avvisa. Un amministratore apre \"Modifica le modalità\" per cambiarle e salva l'intero elenco; Fuori casa e In casa non si possono rimuovere e le modalità sono al massimo otto. Nella scheda di una centrale, il selettore di modalità e il suo pulsante inseriscono nella modalità scelta; una centrale il cui firmware non conosce le modalità mantiene i due pulsanti. Una modalità non cambia mai il PIN, il blocco né le zone di fumo, panico e manomissione, che sorvegliano sempre.",
        "外出、在宅、夜間、または独自のモード。モードごとに、どのゾーンが警戒するか、どれがすぐに、またはエントリー遅延の後に警報を出すか、退出・進入の遅延、サイレンを鳴らすか（無音の警報も記録・通知されます）、サーバーがどれだけ強く知らせるかを決めます。管理者は「モードを編集」を開いて変更し、リスト全体を保存します。外出と在宅は削除できず、モードは最大 8 つです。警報盤のカードでは、モード選択とそのボタンが選んだモードで警戒します。モードに対応しないファームウェアの警報盤は 2 つのボタンのままです。モードが PIN、ロックアウト、常に警戒する煙・非常ボタン・改ざんのゾーンを変えることはありません。",
        "离家、在家、夜间或您自己的模式：每种模式规定哪些分区守护、哪些分区立即报警或在进入延时后报警、退出和进入延时、警笛是否鸣响（静音报警仍会记录和通知）以及服务器通知的力度。管理员打开“编辑模式”进行修改，并保存整个列表；离家和在家不能移除，最多有八种模式。在主机卡片中，模式选择及其按钮按所选模式布防；固件不支持模式的主机保留两个按钮。模式绝不会改变 PIN、锁定，也不会改变始终守护的烟雾、紧急按钮和防拆分区。",
        "Ausente, Em casa, Noite ou o seu: cada modo diz que zonas vigiam, quais disparam o alarme logo ou após o atraso de entrada, os atrasos de saída e de entrada, se a sirene toca (um alarme silencioso fica registado e avisado na mesma) e com que insistência o servidor avisa. Um administrador abre \"Editar os modos\" para os alterar e guarda a lista inteira; Ausente e Em casa não podem ser retirados e há no máximo oito modos. No cartão de uma central, o seletor de modo e o seu botão armam no modo escolhido; uma central cujo firmware não conhece os modos mantém os dois botões. Um modo nunca altera o PIN, o bloqueio nem as zonas de fumo, pânico e sabotagem, que vigiam sempre."] },
    { target: "ap-zigbee", placement: "bottom",
      t: ["Zigbee sensors for the zones", "Sensores Zigbee para las zonas", "Zigbee-Sensoren für die Zonen", "Capteurs Zigbee pour les zones", "Sensori Zigbee per le zone", "ゾーンのZigbeeセンサー", "分区的 Zigbee 传感器", "Sensores Zigbee para as zonas"],
      b: ["While the server holds the Zigbee radio, a panel cannot hear its sensors itself. Here an administrator ties each Zigbee sensor of the device registry to a zone of a panel; the server then tells the panel how that zone is whenever it changes (and every half minute), so arming the panel really guards those doors, windows and motion sensors. When the panel holds the radio itself, it hears them directly and ignores the server's word.",
        "Mientras el servidor tiene la radio Zigbee, la central no oye sus sensores. Aquí un administrador asocia cada sensor Zigbee del registro de dispositivos a una zona de una central; el servidor entonces le dice a la central cómo está esa zona cada vez que cambia (y cada medio minuto), así que armar la central protege de verdad esas puertas, ventanas y sensores de movimiento. Cuando la central tiene la radio, los oye directamente e ignora lo que diga el servidor.",
        "Solange der Server das Zigbee-Funkmodul hält, hört die Zentrale ihre Sensoren nicht selbst. Hier verknüpft ein Administrator jeden Zigbee-Sensor des Geräteregisters mit einer Zone einer Zentrale; der Server meldet der Zentrale dann bei jeder Änderung (und alle 30 Sekunden), wie die Zone ist - so überwacht das Scharfschalten wirklich diese Türen, Fenster und Bewegungsmelder. Hält die Zentrale das Funkmodul selbst, hört sie direkt und ignoriert den Server.",
        "Tant que le serveur tient la radio Zigbee, la centrale n'entend pas ses capteurs. Ici un administrateur associe chaque capteur Zigbee du registre d'appareils à une zone d'une centrale ; le serveur indique alors à la centrale l'état de la zone à chaque changement (et toutes les 30 secondes), donc armer la centrale surveille vraiment ces portes, fenêtres et détecteurs de mouvement. Quand la centrale tient la radio, elle les entend directement et ignore le serveur.",
        "Finché il server tiene la radio Zigbee, la centrale non sente i suoi sensori. Qui un amministratore associa ogni sensore Zigbee del registro dispositivi a una zona di una centrale; il server dice poi alla centrale com'è la zona a ogni cambio (e ogni mezzo minuto), così inserire la centrale protegge davvero quelle porte, finestre e sensori di movimento. Quando la centrale tiene la radio, li sente direttamente e ignora il server.",
        "サーバーがZigbee無線を握っている間、制御盤は自分でセンサーを聞けません。ここで管理者がデバイス登録のZigbeeセンサーを制御盤のゾーンに紐付けると、サーバーがゾーンの変化のたび（および30秒ごと）に状態を制御盤へ伝え、警戒すると本当にそのドア・窓・人感センサーを守れます。制御盤自身が無線を持つ場合は直接受信し、サーバーの情報は無視します。",
        "当服务器持有 Zigbee 无线电时，主机自己听不到传感器。管理员在这里把设备注册表中的每个 Zigbee 传感器关联到某台主机的某个分区；服务器会在分区状态变化时（以及每半分钟）告知主机，因此主机布防后真的能守护这些门、窗和移动传感器。当主机自己持有无线电时，它直接接收并忽略服务器的信息。",
        "Enquanto o servidor tem o rádio Zigbee, a central não ouve os seus sensores. Aqui um administrador associa cada sensor Zigbee do registo de dispositivos a uma zona de uma central; o servidor diz então à central como está a zona sempre que muda (e a cada meio minuto), por isso armar a central protege mesmo essas portas, janelas e sensores de movimento. Quando a central tem o rádio, ouve-os diretamente e ignora o servidor."] },
    { target: "ap-actions", placement: "top",
      t: ["Commands to a panel, and the drawing", "Órdenes a una central y el dibujo", "Befehle an eine Zentrale und die Zeichnung", "Ordres à une centrale et le dessin", "Comandi a una centrale e il disegno", "制御盤へのコマンドと設計図", "对主机的指令与图纸", "Ordens a uma central e o desenho"],
      b: ["An administrator can arm and disarm a panel from here, but only when three things allow it: the server (ARMOR_ALARM_COMMANDS=1), the node (its setting for the server's commands) and the broker (its access list). A disarm asks for your PIN, which the server checks and the node never sees. An accepted command is not an armed alarm: the card shows what the node says next. \"Open the Alarm Designer\" takes you to the drawing, where these panels appear tied to their zones. This is not a certified alarm system.",
        "Un administrador puede armar y desarmar una central desde aquí, pero solo cuando lo permiten tres cosas: el servidor (ARMOR_ALARM_COMMANDS=1), el nodo (su ajuste de órdenes del servidor) y el broker (su lista de acceso). Desarmar pide tu PIN, que comprueba el servidor y el nodo nunca ve. Una orden aceptada no es una alarma armada: la tarjeta muestra lo que dice el nodo después. \"Abrir el Diseñador de alarma\" te lleva al dibujo, donde estas centrales aparecen ligadas a sus zonas. No es un sistema de alarma certificado.",
        "Ein Administrator kann hier eine Zentrale scharf und unscharf schalten, aber nur wenn drei Dinge es erlauben: der Server (ARMOR_ALARM_COMMANDS=1), der Knoten (seine Einstellung für Serverbefehle) und der Broker (seine Zugriffsliste). Das Unscharfschalten verlangt Ihre PIN, die der Server prüft und der Knoten nie sieht. Ein akzeptierter Befehl ist keine scharfe Anlage: Die Karte zeigt, was der Knoten danach meldet. \"Alarm-Designer öffnen\" führt zur Zeichnung. Dies ist kein zertifiziertes Alarmsystem.",
        "Un administrateur peut armer et désarmer une centrale d'ici, mais seulement si trois éléments l'autorisent : le serveur (ARMOR_ALARM_COMMANDS=1), le nœud (son réglage des ordres du serveur) et le broker (sa liste d'accès). Désarmer demande votre PIN, que le serveur vérifie et que le nœud ne voit jamais. Un ordre accepté n'est pas une alarme armée : la carte montre ce que dit ensuite le nœud. « Ouvrir le concepteur d'alarme » mène au dessin. Ce n'est pas un système d'alarme certifié.",
        "Un amministratore può inserire e disinserire una centrale da qui, ma solo se tre cose lo permettono: il server (ARMOR_ALARM_COMMANDS=1), il nodo (la sua impostazione per i comandi del server) e il broker (la sua lista di accesso). Disinserire chiede il tuo PIN, che il server verifica e il nodo non vede mai. Un comando accettato non è un allarme inserito: la scheda mostra ciò che dice poi il nodo. \"Apri il progettista di allarme\" porta al disegno. Non è un sistema di allarme certificato.",
        "管理者はここから制御盤の警戒・解除ができますが、3つが許可している場合に限ります：サーバー（ARMOR_ALARM_COMMANDS=1）、ノード（サーバーのコマンド設定）、ブローカー（アクセスリスト）。解除にはPINが必要で、PINはサーバーが確認しノードには渡りません。受理されたコマンドは「警戒済み」ではなく、その後ノードが返す状態がカードに出ます。「警報設計を開く」で設計図へ移動します。認証済みの警報システムではありません。",
        "管理员可以在这里对主机布防和撤防，但必须三方都允许：服务器（ARMOR_ALARM_COMMANDS=1）、节点（其接受服务器指令的设置）和代理（其访问列表）。撤防需要你的 PIN，由服务器校验，节点永远看不到。被接受的指令不等于已布防：卡片会显示节点随后报告的状态。“打开报警设计器”会带你到图纸。这不是经过认证的报警系统。",
        "Um administrador pode armar e desarmar uma central daqui, mas só quando três coisas o permitem: o servidor (ARMOR_ALARM_COMMANDS=1), o nó (a sua definição das ordens do servidor) e o broker (a sua lista de acesso). Desarmar pede o seu PIN, que o servidor verifica e o nó nunca vê. Uma ordem aceite não é um alarme armado: o cartão mostra o que o nó diz a seguir. \"Abrir o Desenhador de alarme\" leva ao desenho. Não é um sistema de alarme certificado."] },
  ],
  cameras: [
    { target: "cam-grid", placement: "bottom",
      t: ["How many cameras at once", "Cuántas cámaras a la vez", "Wie viele Kameras gleichzeitig", "Combien de caméras à la fois", "Quante telecamere insieme", "同時に表示する台数", "同时显示的摄像头数量", "Quantas câmaras ao mesmo tempo"],
      b: ["The buttons choose the layout: 1, 2, 4, 6, 8, 9, 12 or 16 views. Each place shows a camera and Studio sizes the tiles to the window, with a scrollbar only when they do not fit. From 2 views up, \"Full-screen wall\" shows the cameras of the view over the whole screen with no gaps. The last button opens the camera settings. A heavier layout needs more network and processor, so start with fewer views on a slow connection.",
        "Los botones eligen la disposición: 1, 2, 4, 6, 8, 9, 12 o 16 vistas. Cada sitio muestra una cámara y Studio ajusta las teselas a la ventana, con barra de desplazamiento solo cuando no caben. Desde 2 vistas, \"Muro a pantalla completa\" muestra las cámaras de la vista sobre toda la pantalla sin huecos. El último botón abre los ajustes de cámaras. Una disposición más grande necesita más red y procesador: con una conexión lenta empieza con menos vistas.",
        "Die Knöpfe wählen das Layout: 1, 2, 4, 6, 8, 9, 12 oder 16 Ansichten. Jeder Platz zeigt eine Kamera, und Studio passt die Kacheln dem Fenster an, mit Scrollbalken nur, wenn sie nicht passen. Ab 2 Ansichten zeigt \"Vollbild-Wand\" die Kameras der Ansicht lückenlos über den ganzen Bildschirm. Der letzte Knopf öffnet die Kameraeinstellungen. Ein größeres Layout braucht mehr Netz und Prozessor: Beginnen Sie bei langsamer Verbindung mit weniger Ansichten.",
        "Les boutons choisissent la disposition : 1, 2, 4, 6, 8, 9, 12 ou 16 vues. Chaque emplacement montre une caméra et Studio adapte les vignettes à la fenêtre, avec une barre de défilement seulement si elles ne tiennent pas. À partir de 2 vues, « Mur plein écran » affiche les caméras de la vue sur tout l'écran sans espace. Le dernier bouton ouvre les réglages des caméras. Une disposition plus grande demande plus de réseau et de processeur : sur une connexion lente, commencez avec moins de vues.",
        "I pulsanti scelgono la disposizione: 1, 2, 4, 6, 8, 9, 12 o 16 viste. Ogni posto mostra una telecamera e Studio adatta le tessere alla finestra, con barra di scorrimento solo se non entrano. Da 2 viste, \"Muro a schermo intero\" mostra le telecamere della vista su tutto lo schermo senza spazi. L'ultimo pulsante apre le impostazioni delle telecamere. Una disposizione più grande richiede più rete e processore: con una connessione lenta parti da meno viste.",
        "ボタンでレイアウト（1・2・4・6・8・9・12・16分割）を選びます。各枠に1台ずつ表示され、Studioがウィンドウに合わせてタイルの大きさを調整し、収まらないときだけスクロールバーが出ます。2分割以上では「全画面ウォール」で隙間なく画面全体に表示できます。最後のボタンはカメラ設定を開きます。分割数が多いほど回線とCPUを使うので、遅い回線では少なめから始めましょう。",
        "按钮用于选择布局：1、2、4、6、8、9、12 或 16 个画面。每个位置显示一台摄像头，Studio 会按窗口调整画面大小，放不下时才出现滚动条。从 2 个画面起，“全屏墙”可无缝隙地把该视图的摄像头铺满整个屏幕。最后一个按钮打开摄像头设置。布局越大，占用网络和处理器越多：网速慢时先用较少的画面。",
        "Os botões escolhem a disposição: 1, 2, 4, 6, 8, 9, 12 ou 16 vistas. Cada lugar mostra uma câmara e o Studio ajusta os mosaicos à janela, com barra de deslocação só quando não cabem. A partir de 2 vistas, \"Parede em ecrã inteiro\" mostra as câmaras da vista por todo o ecrã sem espaços. O último botão abre as definições das câmaras. Uma disposição maior pede mais rede e processador: com ligação lenta comece com menos vistas."] },
    { target: "cam-frame", placement: "top",
      t: ["The picture of each camera", "La imagen de cada cámara", "Das Bild jeder Kamera", "L'image de chaque caméra", "L'immagine di ogni telecamera", "各カメラの映像", "每台摄像头的画面", "A imagem de cada câmara"],
      b: ["Every tile is a live picture. A drop-down in the tile changes which camera that place shows; a click selects it and the arrows go to the next or previous one. The tile says if the camera is online or unreachable, or if it has no stream. A camera that stops answering raises an alarm while the system is armed, so a black tile is worth checking: its power, its network, then its address and port in the settings.",
        "Cada tesela es una imagen en vivo. Un desplegable en la tesela cambia qué cámara muestra ese sitio; un clic la selecciona y las flechas van a la siguiente o la anterior. La tesela indica si la cámara está en línea, inalcanzable o sin flujo. Una cámara que deja de responder levanta una alarma con el sistema armado, así que una tesela negra merece revisión: su alimentación, su red y luego su dirección y puerto en los ajustes.",
        "Jede Kachel ist ein Live-Bild. Ein Auswahlmenü in der Kachel ändert, welche Kamera dieser Platz zeigt; ein Klick wählt sie aus, die Pfeile gehen zur nächsten oder vorigen. Die Kachel sagt, ob die Kamera online, nicht erreichbar oder ohne Stream ist. Eine Kamera ohne Antwort löst bei scharfem System einen Alarm aus, daher lohnt sich bei einer schwarzen Kachel die Prüfung: Strom, Netz, dann Adresse und Port in den Einstellungen.",
        "Chaque vignette est une image en direct. Une liste déroulante dans la vignette change la caméra de cet emplacement ; un clic la sélectionne et les flèches passent à la suivante ou à la précédente. La vignette indique si la caméra est en ligne, injoignable ou sans flux. Une caméra qui ne répond plus lève une alarme système armé : une vignette noire mérite donc un contrôle, d'abord alimentation et réseau, puis adresse et port dans les réglages.",
        "Ogni tessera è un'immagine dal vivo. Un menu a tendina nella tessera cambia quale telecamera mostra quel posto; un clic la seleziona e le frecce vanno alla successiva o alla precedente. La tessera dice se la telecamera è online, irraggiungibile o senza flusso. Una telecamera che non risponde solleva un allarme a sistema inserito, quindi una tessera nera merita un controllo: alimentazione, rete, poi indirizzo e porta nelle impostazioni.",
        "各タイルはライブ映像です。タイル内のドロップダウンでその枠に出すカメラを変更し、クリックで選択、矢印で前後のカメラへ移動します。タイルにはオンライン・到達不能・ストリームなしの別が出ます。警戒中に応答しなくなったカメラはアラームを上げるので、黒いタイルは電源、ネットワーク、設定のアドレスとポートの順に確認しましょう。",
        "每个画面都是实时图像。画面中的下拉框可更改该位置显示哪台摄像头；点击选中，箭头可切到下一台或上一台。画面会标明摄像头在线、不可达或无视频流。布防期间摄像头无响应会触发报警，所以黑屏值得检查：先看供电和网络，再看设置中的地址和端口。",
        "Cada mosaico é uma imagem em direto. Uma lista no mosaico muda que câmara esse lugar mostra; um clique seleciona-a e as setas vão para a seguinte ou a anterior. O mosaico diz se a câmara está ligada, inalcançável ou sem fluxo. Uma câmara que deixa de responder levanta um alarme com o sistema armado, por isso um mosaico preto merece verificação: a alimentação, a rede e depois o endereço e a porta nas definições."] },
    { target: "cam-workspace", placement: "left",
      t: ["On a camera: snapshot, record, PTZ and enlarge", "En una cámara: foto, grabar, PTZ y ampliar", "An einer Kamera: Foto, Aufnahme, PTZ, Vergrößern", "Sur une caméra : photo, enregistrer, PTZ et agrandir", "Su una telecamera: foto, registra, PTZ e ingrandisci", "カメラ上の操作：撮影・録画・PTZ・拡大", "摄像头上的操作：拍照、录制、云台和放大", "Numa câmara: foto, gravar, PTZ e ampliar"],
      b: ["Each tile has its own buttons. Snapshot saves a photo into the Recordings menu; the red button records and stops (the tile shows it is recording, also after reloading the page); the enlarge button opens it big. For a motorised camera that supports it, show the PTZ controls to pan, tilt and zoom. The power button turns the camera off or on in Studio. Select a camera before using the PTZ keys, or they do nothing.",
        "Cada tesela tiene sus botones. Foto guarda una imagen en Grabaciones; el botón rojo graba y para (la tesela indica que graba, también tras recargar la página); el de ampliar la abre grande. En una cámara motorizada que lo admita, muestra los controles PTZ para girar, inclinar y hacer zoom. El botón de encendido apaga o enciende la cámara en Studio. Selecciona una cámara antes de usar el PTZ o no hará nada.",
        "Jede Kachel hat eigene Knöpfe. Foto speichert ein Bild unter Aufnahmen; der rote Knopf startet und stoppt die Aufnahme (die Kachel zeigt, dass sie aufnimmt, auch nach dem Neuladen); Vergrößern öffnet sie groß. Bei einer motorisierten Kamera mit Unterstützung blenden Sie die PTZ-Steuerung zum Schwenken, Neigen und Zoomen ein. Der Ein/Aus-Knopf schaltet die Kamera in Studio aus oder ein. Wählen Sie eine Kamera, bevor Sie PTZ benutzen.",
        "Chaque vignette a ses boutons. Photo enregistre une image dans Enregistrements ; le bouton rouge enregistre et arrête (la vignette indique qu'elle enregistre, aussi après rechargement de la page) ; agrandir l'ouvre en grand. Sur une caméra motorisée compatible, affichez les commandes PTZ pour orienter, incliner et zoomer. Le bouton marche/arrêt éteint ou rallume la caméra dans Studio. Sélectionnez une caméra avant d'utiliser le PTZ.",
        "Ogni tessera ha i suoi pulsanti. Foto salva un'immagine in Registrazioni; il pulsante rosso registra e ferma (la tessera indica che registra, anche dopo aver ricaricato la pagina); ingrandisci la apre grande. Su una telecamera motorizzata che lo supporta, mostra i comandi PTZ per brandeggio, inclinazione e zoom. Il pulsante di accensione spegne o accende la telecamera in Studio. Seleziona una telecamera prima di usare il PTZ.",
        "各タイルに専用ボタンがあります。「撮影」は写真を録画ライブラリに保存、赤いボタンで録画開始／停止（録画中はタイルに表示され、ページを再読み込みしても分かります）、拡大ボタンで大きく表示します。対応する電動カメラではPTZ操作を表示してパン・チルト・ズームができます。電源ボタンはStudio上でカメラをオフ／オンにします。PTZを使う前にカメラを選択してください。",
        "每个画面都有自己的按钮。“拍照”会把照片存入录像库；红色按钮开始和停止录制（画面会显示正在录制，刷新页面后也能看出）；放大按钮可大图查看。对于支持的电动摄像头，可显示云台控制进行水平、俯仰和变焦。电源按钮在 Studio 中关闭或开启摄像头。使用云台前请先选中摄像头。",
        "Cada mosaico tem os seus botões. Foto guarda uma imagem em Gravações; o botão vermelho grava e para (o mosaico indica que está a gravar, também depois de recarregar a página); ampliar abre-o em grande. Numa câmara motorizada que o suporte, mostre os controlos PTZ para rodar, inclinar e fazer zoom. O botão de energia desliga ou liga a câmara no Studio. Selecione uma câmara antes de usar o PTZ."] },
    { target: "cam-grid", placement: "bottom",
      t: ["Configure cameras", "Configurar las cámaras", "Kameras einrichten", "Configurer les caméras", "Configurare le telecamere", "カメラの設定", "配置摄像头", "Configurar as câmaras"],
      b: ["The last button of the row opens the camera settings: add a camera with its name, address, RTSP port and path, ONVIF port and, if needed, a snapshot address. \"Discover streams\" helps to find the right path. The user and password go only to your local server, which keeps them encrypted; the browser never keeps them. If you restart the server, sign in again to use the cameras. Typical mistake: a wrong RTSP path gives a tile that says \"no stream\".",
        "El último botón de la fila abre los ajustes de cámaras: añade una cámara con su nombre, dirección, puerto RTSP y ruta, puerto ONVIF y, si hace falta, una dirección para fotos. \"Descubrir flujos\" ayuda a hallar la ruta correcta. El usuario y la contraseña van solo a tu servidor local, que los guarda cifrados; el navegador nunca los guarda. Si reinicias el servidor, vuelve a iniciar sesión para usar las cámaras. Error típico: una ruta RTSP equivocada da una tesela que dice \"sin flujo\".",
        "Der letzte Knopf der Reihe öffnet die Kameraeinstellungen: Kamera mit Name, Adresse, RTSP-Port und -Pfad, ONVIF-Port und bei Bedarf einer Schnappschuss-Adresse hinzufügen. \"Streams suchen\" hilft, den richtigen Pfad zu finden. Benutzer und Passwort gehen nur an Ihren lokalen Server, der sie verschlüsselt speichert; der Browser speichert sie nie. Nach einem Neustart des Servers melden Sie sich erneut an. Typischer Fehler: ein falscher RTSP-Pfad ergibt eine Kachel mit \"kein Stream\".",
        "Le dernier bouton de la rangée ouvre les réglages des caméras : ajoutez une caméra avec son nom, son adresse, son port et chemin RTSP, son port ONVIF et, si besoin, une adresse d'image fixe. « Découvrir les flux » aide à trouver le bon chemin. L'utilisateur et le mot de passe vont seulement à votre serveur local, qui les garde chiffrés ; le navigateur ne les garde jamais. Après un redémarrage du serveur, reconnectez-vous. Erreur typique : un mauvais chemin RTSP donne une vignette « sans flux ».",
        "L'ultimo pulsante della riga apre le impostazioni delle telecamere: aggiungi una telecamera con nome, indirizzo, porta e percorso RTSP, porta ONVIF e, se serve, un indirizzo per le foto. \"Scopri i flussi\" aiuta a trovare il percorso giusto. Utente e password vanno solo al tuo server locale, che li conserva cifrati; il browser non li conserva mai. Dopo un riavvio del server, accedi di nuovo. Errore tipico: un percorso RTSP sbagliato dà una tessera \"senza flusso\".",
        "行の最後のボタンでカメラ設定を開きます。名前、アドレス、RTSPポートとパス、ONVIFポート、必要ならスナップショットのアドレスを入力してカメラを追加します。「ストリームを探す」で正しいパスを見つけられます。ユーザー名とパスワードはローカルサーバーにだけ送られ、暗号化して保存されます。ブラウザーには保存されません。サーバー再起動後は再ログインが必要です。よくある失敗はRTSPパスの誤りで、タイルに「ストリームなし」と出ます。",
        "这一行的最后一个按钮会打开摄像头设置：填写名称、地址、RTSP 端口和路径、ONVIF 端口，必要时填写快照地址即可添加摄像头。“发现视频流”可帮助找到正确的路径。用户名和密码只发送给你的本地服务器，由其加密保存，浏览器从不保存。重启服务器后需要重新登录才能使用摄像头。典型错误：RTSP 路径不对会导致画面显示“无视频流”。",
        "O último botão da fila abre as definições das câmaras: adicione uma câmara com nome, endereço, porta e caminho RTSP, porta ONVIF e, se preciso, um endereço de fotografias. \"Descobrir fluxos\" ajuda a encontrar o caminho certo. O utilizador e a palavra-passe vão só para o seu servidor local, que os guarda cifrados; o navegador nunca os guarda. Se reiniciar o servidor, inicie sessão outra vez. Erro típico: um caminho RTSP errado dá um mosaico \"sem fluxo\"."] },
  ],
  radar: [
    { target: "radar-map", placement: "right",
      t: ["The live map of targets", "El mapa en vivo de blancos", "Die Live-Karte der Ziele", "La carte en direct des cibles", "La mappa dal vivo dei bersagli", "ターゲットのライブマップ", "目标实时地图", "O mapa em direto dos alvos"],
      b: ["Each radar of the site is drawn with the area it covers and each target appears where it stands, in its radar's colour. Targets seen by two radars at once are merged into one. The header counts the targets live and the ones counted for alarms; the legend explains the dots: counted, ignored (inside an ignore zone) and outside the site. The map comes from your site design, so an empty map means the site is not drawn yet.",
        "Cada radar del sitio se dibuja con el área que cubre y cada blanco aparece donde está, con el color de su radar. Los blancos vistos por dos radares a la vez se funden en uno. La cabecera cuenta los blancos en vivo y los contados para alarmas; la leyenda explica los puntos: contado, ignorado (dentro de una zona ignorada) y fuera del sitio. El mapa sale de tu diseño del sitio, así que un mapa vacío significa que aún no está dibujado.",
        "Jedes Radar des Standorts ist mit seinem Erfassungsbereich gezeichnet, und jedes Ziel erscheint dort, wo es steht, in der Farbe seines Radars. Von zwei Radaren zugleich gesehene Ziele werden zu einem verschmolzen. Die Kopfzeile zählt die Live-Ziele und die für Alarme gezählten; die Legende erklärt die Punkte: gezählt, ignoriert (in einer Ignorierzone) und außerhalb des Standorts. Die Karte stammt aus Ihrem Standortentwurf; eine leere Karte heißt: noch nicht gezeichnet.",
        "Chaque radar du site est dessiné avec la zone qu'il couvre et chaque cible apparaît là où elle se trouve, dans la couleur de son radar. Les cibles vues par deux radars à la fois sont fusionnées en une. L'en-tête compte les cibles en direct et celles comptées pour les alarmes ; la légende explique les points : compté, ignoré (dans une zone ignorée) et hors du site. La carte vient de votre plan du site : une carte vide signifie qu'il n'est pas encore dessiné.",
        "Ogni radar del sito è disegnato con l'area che copre e ogni bersaglio compare dove si trova, nel colore del suo radar. I bersagli visti da due radar insieme sono fusi in uno. L'intestazione conta i bersagli dal vivo e quelli contati per gli allarmi; la legenda spiega i punti: contato, ignorato (dentro una zona ignorata) e fuori dal sito. La mappa viene dal progetto del sito: una mappa vuota significa che non è ancora disegnato.",
        "サイトの各レーダーはカバー範囲とともに描かれ、各ターゲットは実際の位置にレーダーの色で表示されます。2台のレーダーが同時に捉えたターゲットは1つに統合されます。見出しにはライブのターゲット数とアラーム対象の数が出て、凡例は点の意味（カウント対象・無視・サイト外）を説明します。地図はサイト設計から作られるため、空ならまだ描かれていません。",
        "站点的每台雷达都会按其覆盖范围绘制，每个目标以所属雷达的颜色显示在实际位置。两台雷达同时看到的目标会合并为一个。标题处统计实时目标数和计入报警的数量；图例说明各个点：计入、忽略（在忽略区内）和站点之外。地图来自你的场地设计，空白说明还没画场地。",
        "Cada radar do local é desenhado com a área que cobre e cada alvo aparece onde está, com a cor do seu radar. Os alvos vistos por dois radares ao mesmo tempo são fundidos num só. O cabeçalho conta os alvos em direto e os contados para alarmes; a legenda explica os pontos: contado, ignorado (dentro de uma zona ignorada) e fora do local. O mapa vem do desenho do local: um mapa vazio significa que ainda não está desenhado."] },
    { target: "radar-controls", placement: "left",
      t: ["Zoom, pan and fit", "Zoom, desplazamiento y ajuste", "Zoomen, Verschieben, Einpassen", "Zoom, déplacement et ajustement", "Zoom, spostamento e adattamento", "ズーム・移動・全体表示", "缩放、平移与适应窗口", "Zoom, deslocação e ajuste"],
      b: ["Use the + and - buttons or the mouse wheel to zoom, drag the map to move it and press the arrows button to fit the whole site in the view again. The map zooms around the pointer, so place the pointer on what you want to see closer. A note under the map reminds you of the axis convention of the radars; if targets appear mirrored, fix it in the settings of that radar.",
        "Usa los botones + y - o la rueda del ratón para ampliar, arrastra el mapa para moverlo y pulsa el botón de las flechas para encajar todo el sitio en la vista otra vez. El mapa se amplía alrededor del puntero, así que coloca el puntero sobre lo que quieres ver más de cerca. Una nota bajo el mapa recuerda la convención de ejes de los radares; si los blancos salen en espejo, corrígelo en los ajustes de ese radar.",
        "Mit den Tasten + und - oder dem Mausrad zoomen, die Karte ziehen zum Verschieben und die Pfeil-Taste passt den ganzen Standort wieder ein. Die Karte zoomt um den Mauszeiger, platzieren Sie ihn also auf dem, was Sie näher sehen wollen. Ein Hinweis unter der Karte erinnert an die Achsenkonvention der Radare; erscheinen Ziele gespiegelt, korrigieren Sie das in den Einstellungen dieses Radars.",
        "Utilisez les boutons + et - ou la molette pour zoomer, faites glisser la carte pour la déplacer et appuyez sur le bouton à flèches pour réajuster tout le site dans la vue. La carte zoome autour du pointeur : placez-le sur ce que vous voulez voir de plus près. Une note sous la carte rappelle la convention des axes des radars ; si les cibles apparaissent en miroir, corrigez-le dans les réglages de ce radar.",
        "Usa i pulsanti + e - o la rotellina per ingrandire, trascina la mappa per spostarla e premi il pulsante con le frecce per far rientrare di nuovo tutto il sito nella vista. La mappa si ingrandisce attorno al puntatore, quindi mettilo su ciò che vuoi vedere da vicino. Una nota sotto la mappa ricorda la convenzione degli assi dei radar; se i bersagli appaiono specchiati, correggilo nelle impostazioni di quel radar.",
        "＋／－ボタンまたはマウスホイールで拡大縮小、ドラッグで移動、矢印ボタンでサイト全体を表示に収め直します。ポインターを中心に拡大されるので、拡大したい場所にポインターを置いてください。地図の下にはレーダーの軸の取り決めの注記があります。ターゲットが左右反転して見える場合は、そのレーダーの設定で直します。",
        "用 + 和 - 按钮或鼠标滚轮缩放，拖动地图平移，按箭头按钮可让整个站点重新适应视图。地图以指针为中心缩放，所以把指针放在想看清的地方。地图下方的注释说明了雷达的坐标轴约定；如果目标显示成镜像，请在该雷达的设置中修正。",
        "Use os botões + e - ou a roda do rato para ampliar, arraste o mapa para o mover e prima o botão das setas para voltar a encaixar todo o local na vista. O mapa amplia em torno do ponteiro, por isso ponha o ponteiro sobre o que quer ver de perto. Uma nota por baixo do mapa lembra a convenção dos eixos dos radares; se os alvos aparecerem em espelho, corrija nas definições desse radar."] },
    { target: "radar-side", placement: "left",
      t: ["Radars of the design and active nodes", "Radares del diseño y nodos activos", "Radare des Entwurfs und aktive Knoten", "Radars du plan et nœuds actifs", "Radar del progetto e nodi attivi", "設計のレーダーと稼働中ノード", "设计中的雷达与活动节点", "Radares do desenho e nós ativos"],
      b: ["Two tabs. \"Radars of the design\" lists the radars you drew, each with its settings; \"Active radar nodes\" lists the field nodes that are reporting, with their state and, when they publish their address, a Panel link to open the node's own web panel. A node that appears here but whose radar is not in the design explains why its targets do not show on the map: bind it in the first tab.",
        "Dos pestañas. \"Radares del diseño\" lista los radares que dibujaste, cada uno con sus ajustes; \"Nodos de radar activos\" lista los nodos de campo que informan, con su estado y, si publican su dirección, un enlace Panel para abrir el panel web del propio nodo. Un nodo que sale aquí pero cuyo radar no está en el diseño explica por qué sus blancos no salen en el mapa: asócialo en la primera pestaña.",
        "Zwei Reiter. \"Radare des Entwurfs\" listet die gezeichneten Radare, jedes mit seinen Einstellungen; \"Aktive Radarknoten\" listet die berichtenden Feldknoten mit Zustand und, falls sie ihre Adresse veröffentlichen, einem Panel-Link zum eigenen Web-Panel des Knotens. Ein Knoten, der hier erscheint, dessen Radar aber nicht im Entwurf ist, erklärt, warum seine Ziele nicht auf der Karte sind: im ersten Reiter zuordnen.",
        "Deux onglets. « Radars du plan » liste les radars dessinés, chacun avec ses réglages ; « Nœuds radar actifs » liste les nœuds de terrain qui rapportent, avec leur état et, s'ils publient leur adresse, un lien Panneau pour ouvrir le panneau web du nœud. Un nœud présent ici dont le radar n'est pas dans le plan explique pourquoi ses cibles n'apparaissent pas sur la carte : associez-le dans le premier onglet.",
        "Due schede. \"Radar del progetto\" elenca i radar disegnati, ciascuno con le sue impostazioni; \"Nodi radar attivi\" elenca i nodi di campo che riferiscono, con il loro stato e, se pubblicano il loro indirizzo, un collegamento Pannello per aprire il pannello web del nodo. Un nodo che compare qui ma il cui radar non è nel progetto spiega perché i suoi bersagli non si vedono sulla mappa: associalo nella prima scheda.",
        "タブは2つ。「設計のレーダー」は描いたレーダーを設定付きで一覧表示し、「稼働中のレーダーノード」は報告中の現場ノードを状態付きで一覧表示します（アドレスを公開しているノードにはそのノード自身のWebパネルを開く「パネル」リンクが付きます）。ここに出るのに設計にレーダーがないノードは、ターゲットが地図に出ない理由です。最初のタブで紐付けてください。",
        "有两个标签页。“设计中的雷达”列出你绘制的雷达及其设置；“活动雷达节点”列出正在上报的现场节点及其状态，若节点发布了自己的地址，还会有“面板”链接，可打开节点自带的网页面板。出现在这里但其雷达不在设计中的节点，就是目标不出现在地图上的原因：请在第一个标签页中关联它。",
        "Dois separadores. \"Radares do desenho\" lista os radares que desenhou, cada um com as suas definições; \"Nós de radar ativos\" lista os nós de campo que comunicam, com o seu estado e, se publicarem o endereço, uma ligação Painel para abrir o painel web do próprio nó. Um nó que aparece aqui mas cujo radar não está no desenho explica porque os seus alvos não aparecem no mapa: associe-o no primeiro separador."] },
    { target: "radar-sensors", placement: "left",
      t: ["Set up a radar: node, position and direction", "Ajustar un radar: nodo, posición y dirección", "Ein Radar einrichten: Knoten, Position, Richtung", "Régler un radar : nœud, position et direction", "Impostare un radar: nodo, posizione e direzione", "レーダーの設定：ノード・位置・向き", "设置雷达：节点、位置与方向", "Configurar um radar: nó, posição e direção"],
      b: ["Open a radar to set which field node and channel report for it, where it stands (position and height) and which way it faces. What you set here draws its coverage and places its targets; the radar module keeps the configuration flashed in its node. \"Mirror sideways axis\" fixes a radar mounted the other way round. \"Ignore zones\" are areas where nothing is reported (a tree that moves, a fan): drag on the plane to draw one. Mistake: a wrong direction puts every target on the wrong side of the house.",
        "Abre un radar para fijar qué nodo de campo y canal informan por él, dónde está (posición y altura) y hacia dónde mira. Lo que fijes aquí dibuja su cobertura y coloca sus blancos; el módulo del radar guarda la configuración grabada en su nodo. \"Espejar el eje lateral\" corrige un radar montado al revés. Las \"Zonas ignoradas\" son áreas donde no se informa nada (un árbol que se mueve, un ventilador): arrastra sobre el plano para dibujar una. Error: una dirección equivocada pone cada blanco al otro lado de la casa.",
        "Öffnen Sie ein Radar, um festzulegen, welcher Feldknoten und Kanal für es berichten, wo es steht (Position und Höhe) und wohin es blickt. Das Eingestellte zeichnet seine Abdeckung und platziert seine Ziele; das Radarmodul behält die in seinem Knoten gespeicherte Konfiguration. \"Seitenachse spiegeln\" korrigiert ein verkehrt montiertes Radar. \"Ignorierzonen\" sind Bereiche ohne Meldung (ein bewegter Baum, ein Ventilator): ziehen Sie auf dem Plan eine auf. Fehler: Eine falsche Richtung setzt jedes Ziel auf die falsche Hausseite.",
        "Ouvrez un radar pour fixer quel nœud de terrain et quel canal rapportent pour lui, où il se trouve (position et hauteur) et vers où il regarde. Ce que vous réglez dessine sa couverture et place ses cibles ; le module radar garde la configuration écrite dans son nœud. « Inverser l'axe latéral » corrige un radar monté à l'envers. Les « zones ignorées » sont des zones où rien n'est rapporté (un arbre qui bouge, un ventilateur) : tracez-en une en glissant sur le plan. Erreur : une mauvaise direction met chaque cible du mauvais côté de la maison.",
        "Apri un radar per impostare quale nodo di campo e canale riferiscono per lui, dove si trova (posizione e altezza) e verso dove guarda. Ciò che imposti disegna la sua copertura e colloca i suoi bersagli; il modulo radar conserva la configurazione scritta nel suo nodo. \"Specchia l'asse laterale\" corregge un radar montato al contrario. Le \"zone ignorate\" sono aree dove non si riferisce nulla (un albero che si muove, una ventola): trascina sul piano per disegnarne una. Errore: una direzione sbagliata mette ogni bersaglio dal lato sbagliato della casa.",
        "レーダーを開いて、どの現場ノード・チャンネルが報告するか、設置位置（位置と高さ）、向きを設定します。ここでの設定がカバー範囲の描画とターゲットの配置に使われ、レーダーモジュール自体はノードに書き込まれた設定を保持します。「横軸を反転」は逆向きに取り付けたレーダーを直します。「無視ゾーン」は何も報告しない領域（揺れる木、扇風機）で、平面上をドラッグして描きます。向きの間違いはターゲットを家の反対側に出してしまいます。",
        "打开一台雷达，设置由哪个现场节点和通道为其上报、它的位置（位置和高度）以及朝向。这里的设置用于绘制其覆盖范围并放置目标；雷达模块自身保存着刷写在节点里的配置。“镜像横轴”可修正装反的雷达。“忽略区”是不上报任何内容的区域（会动的树、风扇）：在平面上拖动即可绘制。错误示例：方向设错会让所有目标出现在房子的另一侧。",
        "Abra um radar para definir que nó de campo e canal comunicam por ele, onde está (posição e altura) e para onde olha. O que definir aqui desenha a sua cobertura e coloca os seus alvos; o módulo do radar guarda a configuração gravada no seu nó. \"Espelhar o eixo lateral\" corrige um radar montado ao contrário. As \"zonas ignoradas\" são áreas onde nada é comunicado (uma árvore que se mexe, uma ventoinha): arraste no plano para desenhar uma. Erro: uma direção errada põe cada alvo do lado errado da casa."] },
    { target: "radar-sensors", placement: "left",
      t: ["Add a 270° node and the sensor models", "Añadir un nodo de 270° y los modelos de sensor", "Einen 270°-Knoten und die Sensormodelle hinzufügen", "Ajouter un nœud de 270° et les modèles de capteur", "Aggiungere un nodo da 270° e i modelli di sensore", "270°ノードの追加とセンサーモデル", "添加 270° 节点与传感器型号", "Adicionar um nó de 270° e os modelos de sensor"],
      b: ["A node with three radars (LD2450) covers about 270 degrees: \"Add a 270° node\" creates the three radars in one place, ready for you to move to where the node is mounted. A port may carry an LD2450 or an LD2461 (trackers that feed the perimeter) or a presence sensor, chosen in the node's own panel. Trackers give positions on the map; presence sensors become devices that report presence and distance.",
        "Un nodo con tres radares (LD2450) cubre unos 270 grados: \"Añadir un nodo de 270°\" crea los tres radares en un punto, listos para llevarlos a donde está montado el nodo. Un puerto puede llevar un LD2450 o un LD2461 (rastreadores que alimentan el perímetro) o un sensor de presencia, elegido en el panel del propio nodo. Los rastreadores dan posiciones en el mapa; los sensores de presencia se vuelven dispositivos que informan presencia y distancia.",
        "Ein Knoten mit drei Radaren (LD2450) deckt etwa 270 Grad ab: \"270°-Knoten hinzufügen\" legt die drei Radare an einer Stelle an, bereit zum Verschieben dorthin, wo der Knoten montiert ist. Ein Port kann einen LD2450 oder LD2461 (Tracker, die den Perimeter speisen) oder einen Präsenzsensor tragen, gewählt im eigenen Panel des Knotens. Tracker liefern Positionen auf der Karte; Präsenzsensoren werden zu Geräten, die Anwesenheit und Abstand melden.",
        "Un nœud à trois radars (LD2450) couvre environ 270 degrés : « Ajouter un nœud de 270° » crée les trois radars au même endroit, prêts à être déplacés là où le nœud est monté. Un port peut porter un LD2450 ou un LD2461 (traqueurs qui alimentent le périmètre) ou un capteur de présence, choisi dans le panneau du nœud. Les traqueurs donnent des positions sur la carte ; les capteurs de présence deviennent des appareils qui rapportent présence et distance.",
        "Un nodo con tre radar (LD2450) copre circa 270 gradi: \"Aggiungi un nodo da 270°\" crea i tre radar in un punto, pronti da spostare dove è montato il nodo. Una porta può portare un LD2450 o un LD2461 (tracker che alimentano il perimetro) o un sensore di presenza, scelto nel pannello del nodo. I tracker danno posizioni sulla mappa; i sensori di presenza diventano dispositivi che riferiscono presenza e distanza.",
        "3台のレーダー（LD2450）を持つノードは約270度をカバーします。「270°ノードを追加」で3台のレーダーが1か所に作られるので、ノードの取り付け位置へ移動します。各ポートにはLD2450／LD2461（境界に使うトラッカー）か在室センサーを接続でき、ノード自身のパネルで選びます。トラッカーは地図上に位置を出し、在室センサーは在室と距離を報告するデバイスになります。",
        "带三台雷达（LD2450）的节点可覆盖约 270 度：“添加 270° 节点”会在同一位置创建三台雷达，之后把它们移到节点的安装位置。每个端口可接 LD2450 或 LD2461（为周界提供数据的跟踪器）或存在传感器，在节点自己的面板中选择。跟踪器在地图上给出位置；存在传感器则成为报告存在与距离的设备。",
        "Um nó com três radares (LD2450) cobre cerca de 270 graus: \"Adicionar um nó de 270°\" cria os três radares num ponto, prontos para levar para onde o nó está montado. Uma porta pode levar um LD2450 ou um LD2461 (seguidores que alimentam o perímetro) ou um sensor de presença, escolhido no painel do próprio nó. Os seguidores dão posições no mapa; os sensores de presença tornam-se dispositivos que comunicam presença e distância."] },
  ],
  record: [
    { target: "rec-filters", placement: "bottom",
      t: ["Filters and the recording state", "Filtros y estado de grabación", "Filter und Aufnahmestatus", "Filtres et état d'enregistrement", "Filtri e stato di registrazione", "フィルターと録画状態", "筛选与录制状态", "Filtros e estado da gravação"],
      b: ["Filters pick everything, only photos or only recordings. The line under them says which cameras are recording right now (with a red dot) or how many items there are, and it still knows after reloading the page. Photos and recordings come from the Cameras menu (Snapshot and the red button) and, with the perimeter armed, from the automatic capture.",
        "Los filtros eligen todo, solo fotos o solo grabaciones. La línea de debajo dice qué cámaras graban ahora mismo (con un punto rojo) o cuántos elementos hay, y lo sabe también tras recargar la página. Las fotos y grabaciones vienen del menú Cámaras (Foto y el botón rojo) y, con el perímetro armado, de la captura automática.",
        "Die Filter wählen alles, nur Fotos oder nur Aufnahmen. Die Zeile darunter sagt, welche Kameras gerade aufnehmen (mit rotem Punkt) oder wie viele Einträge es gibt, auch nach dem Neuladen der Seite. Fotos und Aufnahmen stammen aus dem Menü Kameras (Foto und roter Knopf) und, bei scharfem Perimeter, aus der automatischen Aufnahme.",
        "Les filtres choisissent tout, seulement les photos ou seulement les enregistrements. La ligne dessous indique quelles caméras enregistrent en ce moment (point rouge) ou combien d'éléments il y a, et elle le sait aussi après rechargement de la page. Photos et enregistrements viennent du menu Caméras (Photo et bouton rouge) et, périmètre armé, de la capture automatique.",
        "I filtri scelgono tutto, solo foto o solo registrazioni. La riga sotto dice quali telecamere registrano adesso (con un punto rosso) o quanti elementi ci sono, e lo sa anche dopo aver ricaricato la pagina. Foto e registrazioni vengono dal menu Telecamere (Foto e pulsante rosso) e, a perimetro inserito, dalla cattura automatica.",
        "フィルターで「すべて」「写真のみ」「録画のみ」を選びます。その下の行には、いま録画中のカメラ（赤い点付き）または件数が出て、ページを再読み込みしても把握しています。写真と録画はカメラメニュー（撮影と赤いボタン）から作られ、警戒中は自動キャプチャからも保存されます。",
        "筛选器可选择全部、仅照片或仅录像。下方一行显示正在录制的摄像头（带红点）或项目总数，刷新页面后依然准确。照片和录像来自“摄像头”菜单（拍照和红色按钮），周界布防时也来自自动抓拍。",
        "Os filtros escolhem tudo, só fotos ou só gravações. A linha por baixo diz que câmaras estão a gravar agora (com um ponto vermelho) ou quantos itens há, e sabe-o também depois de recarregar a página. As fotos e gravações vêm do menu Câmaras (Foto e o botão vermelho) e, com o perímetro armado, da captura automática."] },
    { target: "rec-list", placement: "right",
      t: ["The list and the preview", "La lista y la vista previa", "Die Liste und die Vorschau", "La liste et l'aperçu", "L'elenco e l'anteprima", "一覧とプレビュー", "列表与预览", "A lista e a pré-visualização"],
      b: ["On the left, every photo and recording with its camera, date and size, newest first. Tick the ones you want to act on. Choose one and it opens on the right: a photo is shown large, a recording plays with its controls. Use it to check what a camera saw before and after an alarm.",
        "A la izquierda, cada foto y grabación con su cámara, fecha y tamaño, la más nueva primero. Marca las que quieras tratar. Elige una y se abre a la derecha: una foto se ve grande, una grabación se reproduce con sus controles. Úsalo para ver qué vio una cámara antes y después de una alarma.",
        "Links jedes Foto und jede Aufnahme mit Kamera, Datum und Größe, das neueste zuerst. Haken Sie die an, die Sie bearbeiten wollen. Wählen Sie eine, und sie öffnet sich rechts: Ein Foto wird groß gezeigt, eine Aufnahme mit ihren Bedienelementen abgespielt. So prüfen Sie, was eine Kamera vor und nach einem Alarm sah.",
        "À gauche, chaque photo et enregistrement avec sa caméra, sa date et sa taille, le plus récent d'abord. Cochez ceux que vous voulez traiter. Choisissez-en un et il s'ouvre à droite : une photo s'affiche en grand, un enregistrement se lit avec ses commandes. Utile pour voir ce qu'une caméra a vu avant et après une alarme.",
        "A sinistra, ogni foto e registrazione con telecamera, data e dimensione, la più recente per prima. Seleziona quelle su cui vuoi agire. Scegline una e si apre a destra: una foto è mostrata grande, una registrazione si riproduce con i suoi controlli. Serve a vedere cosa ha visto una telecamera prima e dopo un allarme.",
        "左側に、すべての写真と録画がカメラ名・日時・サイズ付きで新しい順に並びます。操作したいものにチェックを入れます。1つ選ぶと右側に開き、写真は大きく表示、録画は操作ボタン付きで再生されます。アラームの前後にカメラが何を見たかの確認に使えます。",
        "左侧按时间倒序列出所有照片和录像，带有摄像头、日期和大小。勾选要处理的项目。选中一项后会在右侧打开：照片大图显示，录像带控制按钮播放。可用它查看报警前后摄像头拍到了什么。",
        "À esquerda, cada foto e gravação com a sua câmara, data e tamanho, a mais recente primeiro. Marque as que quer tratar. Escolha uma e abre-se à direita: uma foto vê-se em grande, uma gravação reproduz-se com os seus controlos. Use-o para ver o que uma câmara viu antes e depois de um alarme."] },
    { target: "rec-preview", placement: "left",
      t: ["Keep, delete and proof of custody", "Conservar, borrar y prueba de custodia", "Behalten, löschen und Verwahrnachweis", "Garder, supprimer et preuve de conservation", "Conservare, eliminare e prova di custodia", "保護・削除・保管証明", "保留、删除与保管证明", "Guardar, apagar e prova de custódia"],
      b: ["\"Keep (protect)\" keeps the item out of the automatic pruning (the server keeps 30 days or 20 GB, oldest first) and out of bulk clean-ups until you release it: use it for what may be evidence. \"Proof of custody\" downloads a file signed by the server with the size, the SHA-256 of the evidence as it is now, when it was made and the audit lines about it. Deleting is permanent and Studio asks first: protect before you clean.",
        "\"Conservar (proteger)\" deja el elemento fuera de la poda automática (el servidor guarda 30 días o 20 GB, lo más antiguo primero) y de las limpiezas en bloque hasta que lo liberes: úsalo para lo que pueda ser prueba. \"Prueba de custodia\" descarga un archivo firmado por el servidor con el tamaño, el SHA-256 de la prueba tal como está ahora, cuándo se hizo y las líneas de auditoría sobre ella. Borrar es permanente y Studio pregunta antes: protege antes de limpiar.",
        "\"Behalten (schützen)\" nimmt den Eintrag aus der automatischen Bereinigung (der Server behält 30 Tage oder 20 GB, das Älteste zuerst) und aus Sammellöschungen, bis Sie ihn freigeben: nutzen Sie es für mögliche Beweise. \"Verwahrnachweis\" lädt eine vom Server signierte Datei mit Größe, SHA-256 des Beweises im aktuellen Zustand, Erstellungszeit und den Audit-Zeilen dazu herunter. Löschen ist endgültig, Studio fragt vorher: erst schützen, dann aufräumen.",
        "« Garder (protéger) » met l'élément à l'abri de l'élagage automatique (le serveur garde 30 jours ou 20 Go, le plus ancien d'abord) et des nettoyages en masse jusqu'à ce que vous le libériez : à utiliser pour ce qui peut servir de preuve. « Preuve de conservation » télécharge un fichier signé par le serveur avec la taille, le SHA-256 de la preuve en l'état, la date de création et les lignes d'audit. Supprimer est définitif et Studio demande d'abord : protégez avant de nettoyer.",
        "\"Conserva (proteggi)\" tiene l'elemento fuori dalla potatura automatica (il server tiene 30 giorni o 20 GB, il più vecchio per primo) e dalle pulizie di massa finché non lo rilasci: usalo per ciò che può essere una prova. \"Prova di custodia\" scarica un file firmato dal server con dimensione, SHA-256 della prova com'è ora, quando è stato creato e le righe di audit. Eliminare è permanente e Studio chiede prima: proteggi prima di pulire.",
        "「保護」すると、解除するまで自動削除（サーバーは30日または20GBを保持し、古い順に削除）と一括削除の対象外になります。証拠になり得るものに使いましょう。「保管証明」は、サイズ、現在のSHA-256、作成時刻、関連する監査記録を含む、サーバー署名付きのファイルをダウンロードします。削除は元に戻せず、Studioが先に確認します。整理の前に保護を。",
        "“保留（保护）”会让该项目免于自动清理（服务器保留 30 天或 20 GB，先删最旧的）和批量清理，直到你解除保护：用于可能成为证据的内容。“保管证明”会下载一份由服务器签名的文件，包含大小、证据当前的 SHA-256、生成时间及相关审计记录。删除是永久的，Studio 会先询问：清理前先保护。",
        "\"Guardar (proteger)\" deixa o item fora da limpeza automática (o servidor guarda 30 dias ou 20 GB, o mais antigo primeiro) e das limpezas em bloco até o libertar: use-o para o que possa ser prova. \"Prova de custódia\" descarrega um ficheiro assinado pelo servidor com o tamanho, o SHA-256 da prova como está agora, quando foi feita e as linhas de auditoria sobre ela. Apagar é permanente e o Studio pergunta antes: proteja antes de limpar."] },
    { target: "rec-status", placement: "bottom",
      t: ["Clean up in bulk, and automatic capture", "Limpiar en bloque y captura automática", "Sammelbereinigung und automatische Aufnahme", "Nettoyer en masse et capture automatique", "Pulire in blocco e cattura automatica", "一括整理と自動キャプチャ", "批量清理与自动抓拍", "Limpar em bloco e captura automática"],
      b: ["Besides \"Delete selected\", you can clean everything of the chosen kind or only what is older than a number of days; protected items are never touched. With the perimeter armed, when a camera sees something the server takes photos and a video by itself and they appear here with the others. How many, how long and how often is set in Configuration > Automatic capture, where you also set a quiet time so someone walking by does not fill the disk.",
        "Además de \"Borrar seleccionados\", puedes limpiar todo lo de un tipo o solo lo más antiguo que un número de días; los elementos protegidos no se tocan nunca. Con el perímetro armado, cuando una cámara ve algo el servidor hace fotos y un vídeo por sí mismo y aparecen aquí con las demás. Cuántas, cuánto y cada cuánto se fija en Configuración > Captura automática, donde también pones un tiempo de calma para que alguien que pasa no llene el disco.",
        "Neben \"Ausgewählte löschen\" können Sie alles der gewählten Art bereinigen oder nur, was älter als eine Anzahl Tage ist; geschützte Einträge bleiben unberührt. Bei scharfem Perimeter macht der Server, wenn eine Kamera etwas sieht, selbst Fotos und ein Video, die hier erscheinen. Wie viele, wie lange und wie oft, stellen Sie unter Konfiguration > Automatische Aufnahme ein, samt einer Ruhezeit, damit ein Passant nicht die Platte füllt.",
        "Outre « Supprimer la sélection », vous pouvez nettoyer tout ce qui est du type choisi ou seulement ce qui a plus de N jours ; les éléments protégés ne sont jamais touchés. Périmètre armé, quand une caméra voit quelque chose, le serveur prend seul des photos et une vidéo qui apparaissent ici avec les autres. Combien, combien de temps et à quelle fréquence se règle dans Configuration > Capture automatique, avec un temps de repos pour qu'un passant ne remplisse pas le disque.",
        "Oltre a \"Elimina selezionati\", puoi pulire tutto il tipo scelto o solo ciò che è più vecchio di un numero di giorni; gli elementi protetti non si toccano mai. A perimetro inserito, quando una telecamera vede qualcosa il server scatta foto e un video da solo e compaiono qui con gli altri. Quante, quanto e ogni quanto si imposta in Configurazione > Cattura automatica, dove metti anche un tempo di quiete perché chi passa non riempia il disco.",
        "「選択を削除」のほか、選んだ種類をすべて、または指定日数より古いものだけを整理できます。保護済みの項目には一切触れません。警戒中にカメラが何かを捉えると、サーバーが自動で写真と動画を保存し、ここに並びます。枚数・長さ・間隔は「設定 > 自動キャプチャ」で決め、通りがかりでディスクが埋まらないよう待機時間も設定できます。",
        "除“删除所选”外，还可以清理所选类型的全部内容，或只清理超过若干天的内容；受保护的项目绝不会被动。周界布防时，摄像头一旦发现情况，服务器会自动拍照并录一段视频，同样出现在这里。数量、时长和频率在“配置 > 自动抓拍”中设置，那里还可设置静默时间，避免路人把磁盘填满。",
        "Além de \"Apagar selecionados\", pode limpar tudo do tipo escolhido ou só o que é mais antigo do que um número de dias; os itens protegidos nunca são tocados. Com o perímetro armado, quando uma câmara vê algo o servidor tira fotos e um vídeo sozinho e aparecem aqui com as outras. Quantas, quanto tempo e com que frequência define-se em Configuração > Captura automática, onde também define um tempo de calma para quem passa não encher o disco."] },
  ],
  history: [
    { target: "his-tabs", placement: "bottom",
      t: ["Tabs: alarms, connections, devices, system, settings", "Pestañas: alarmas, conexiones, dispositivos, sistema, ajustes", "Reiter: Alarme, Verbindungen, Geräte, System, Einstellungen", "Onglets : alarmes, connexions, appareils, système, réglages", "Schede: allarmi, connessioni, dispositivi, sistema, impostazioni", "タブ：アラーム・接続・デバイス・システム・設定", "标签：报警、连接、设备、系统、设置", "Separadores: alarmes, ligações, dispositivos, sistema, definições"],
      b: ["These tabs split the story by what it is about. \"Connections\" shows every device and app that talks to the server - Studio, the Android app, the panels of the nodes, the voice service - with its last sign of life and its open sessions, and below it who signed in, who was refused and who signed out. \"System\" tells when a node appeared or disappeared (with its firmware), when the broker link dropped, which service was restarted, which update was installed and when the alarm was armed, disarmed or silenced; \"Settings\" tells what was changed and by whom, never the values. Only administrators see addresses and user agents.",
        "Estas pestañas separan la historia según de qué trata. \"Conexiones\" muestra cada dispositivo y app que habla con el servidor - Studio, la app Android, los paneles de los nodos, el servicio de voz - con su última señal de vida y sus sesiones abiertas, y debajo quién entró, a quién se rechazó y quién salió. \"Sistema\" cuenta cuándo un nodo apareció o desapareció (con su firmware), cuándo cayó el enlace con el broker, qué servicio se reinició, qué actualización se instaló y cuándo se armó, desarmó o silenció la alarma; \"Ajustes\" cuenta qué se cambió y quién, nunca los valores. Solo los administradores ven direcciones y agentes de usuario.",
        "Diese Reiter teilen die Geschichte nach ihrem Thema. \"Verbindungen\" zeigt jedes Gerät und jede App, die mit dem Server spricht - Studio, die Android-App, die Panels der Knoten, den Sprachdienst - mit letztem Lebenszeichen und offenen Sitzungen, darunter wer sich angemeldet hat, wer abgelehnt wurde und wer sich abgemeldet hat. \"System\" berichtet, wann ein Knoten auftauchte oder verschwand (mit Firmware), wann die Broker-Verbindung abriss, welcher Dienst neu gestartet, welches Update installiert und wann der Alarm scharf, unscharf oder stumm geschaltet wurde; \"Einstellungen\" zeigt, was wer geändert hat, nie die Werte. Adressen und User-Agents sehen nur Administratoren.",
        "Ces onglets séparent l'histoire selon son sujet. « Connexions » montre chaque appareil et application qui parle au serveur - Studio, l'appli Android, les panneaux des nœuds, le service vocal - avec son dernier signe de vie et ses sessions ouvertes, et dessous qui s'est connecté, qui a été refusé et qui s'est déconnecté. « Système » dit quand un nœud est apparu ou a disparu (avec son firmware), quand le lien avec le broker est tombé, quel service a été redémarré, quelle mise à jour installée et quand l'alarme a été armée, désarmée ou coupée ; « Réglages » dit ce qui a été changé et par qui, jamais les valeurs. Seuls les administrateurs voient adresses et agents utilisateur.",
        "Queste schede dividono la storia per argomento. \"Connessioni\" mostra ogni dispositivo e app che parla con il server - Studio, l'app Android, i pannelli dei nodi, il servizio vocale - con l'ultimo segno di vita e le sessioni aperte, e sotto chi ha effettuato l'accesso, a chi è stato rifiutato e chi è uscito. \"Sistema\" dice quando un nodo è apparso o scomparso (con il firmware), quando è caduto il collegamento con il broker, quale servizio è stato riavviato, quale aggiornamento installato e quando l'allarme è stato inserito, disinserito o silenziato; \"Impostazioni\" dice cosa è stato cambiato e da chi, mai i valori. Solo gli amministratori vedono indirizzi e user agent.",
        "これらのタブは履歴を内容ごとに分けます。「接続」には、サーバーと通信するすべてのデバイスとアプリ（Studio、Android アプリ、ノードのパネル、音声サービス）が最終応答と開いているセッションとともに並び、その下に、サインインした人、拒否された人、サインアウトした人が出ます。「システム」は、ノードの出現・消失（ファームウェア付き）、ブローカー接続の切断、再起動したサービス、インストールした更新、警戒の開始・解除・サイレン停止を示し、「設定」は何をだれが変えたかを示します（値は出ません）。アドレスとユーザーエージェントは管理者だけに見えます。",
        "这些标签按内容划分历史。“连接”显示所有与服务器通信的设备和应用——Studio、Android 应用、节点面板、语音服务——及其最近的活动和已打开的会话，下方是谁登录、谁被拒绝、谁退出。“系统”记录节点何时出现或消失（含固件）、代理连接何时中断、哪个服务重启、安装了哪个更新，以及报警何时布防、撤防或静音；“设置”记录改了什么、谁改的，绝不含具体值。只有管理员能看到地址和用户代理。",
        "Estes separadores dividem a história pelo assunto. \"Ligações\" mostra cada dispositivo e aplicação que fala com o servidor - o Studio, a app Android, os painéis dos nós, o serviço de voz - com o último sinal de vida e as sessões abertas, e por baixo quem iniciou sessão, a quem foi recusado e quem saiu. \"Sistema\" diz quando um nó apareceu ou desapareceu (com o firmware), quando caiu a ligação ao broker, que serviço foi reiniciado, que atualização foi instalada e quando o alarme foi armado, desarmado ou silenciado; \"Definições\" diz o que foi alterado e por quem, nunca os valores. Só os administradores veem endereços e agentes de utilizador."] },
    { target: "his-stats", placement: "bottom",
      t: ["The summary counters", "Los contadores del resumen", "Die Zähler der Zusammenfassung", "Les compteurs du résumé", "I contatori del riepilogo", "サマリーのカウンター", "摘要计数器", "Os contadores do resumo"],
      b: ["On top, the events held, those of the last 24 hours, the HIGH alerts, the incidents of nodes and the span of time the history covers. They tell you in a glance whether the last day was quiet: a high number of HIGH alerts or node incidents is the reason to read the list below. The numbers follow the filters of the server, not the ones you set in the list.",
        "Arriba, los eventos guardados, los de las últimas 24 horas, las alertas ALTAS, los incidentes de nodos y el periodo que cubre el historial. Dicen de un vistazo si el último día fue tranquilo: un número alto de alertas ALTAS o de incidentes de nodos es el motivo para leer la lista de abajo. Las cifras siguen los datos del servidor, no los filtros que pongas en la lista.",
        "Oben die gespeicherten Ereignisse, die der letzten 24 Stunden, die HOHEN Warnungen, die Knotenvorfälle und der Zeitraum, den der Verlauf abdeckt. Sie zeigen auf einen Blick, ob der letzte Tag ruhig war: Viele HOHE Warnungen oder Knotenvorfälle sind der Grund, die Liste darunter zu lesen. Die Zahlen folgen den Serverdaten, nicht den Filtern der Liste.",
        "En haut, les événements conservés, ceux des dernières 24 heures, les alertes ÉLEVÉES, les incidents de nœuds et la période couverte par l'historique. Ils disent d'un coup d'œil si la dernière journée a été calme : beaucoup d'alertes ÉLEVÉES ou d'incidents de nœuds est la raison de lire la liste dessous. Les chiffres suivent les données du serveur, pas les filtres de la liste.",
        "In alto, gli eventi conservati, quelli delle ultime 24 ore, gli avvisi ALTI, gli incidenti dei nodi e il periodo coperto dalla cronologia. Dicono a colpo d'occhio se l'ultimo giorno è stato tranquillo: molti avvisi ALTI o incidenti dei nodi sono il motivo per leggere l'elenco sotto. I numeri seguono i dati del server, non i filtri dell'elenco.",
        "上部には、保持しているイベント数、直近24時間の数、高レベルの警告、ノードのインシデント、履歴が対象とする期間が出ます。直近1日が静かだったかが一目で分かり、高レベルやノードのインシデントが多ければ下の一覧を読む理由になります。数値はサーバーのデータに基づき、一覧に付けたフィルターには連動しません。",
        "顶部显示已保存的事件数、最近 24 小时的数量、高级警报、节点事件，以及历史所覆盖的时间跨度。一眼就能看出最近一天是否平静：高级警报或节点事件很多，就值得细读下面的列表。这些数字来自服务器数据，不受列表中筛选条件影响。",
        "Em cima, os eventos guardados, os das últimas 24 horas, os alertas ALTOS, os incidentes de nós e o período que o histórico cobre. Dizem de relance se o último dia foi calmo: muitos alertas ALTOS ou incidentes de nós são o motivo para ler a lista de baixo. Os números seguem os dados do servidor, não os filtros da lista."] },
    { target: "his-filters", placement: "bottom",
      t: ["Filters, search and period", "Filtros, búsqueda y periodo", "Filter, Suche und Zeitraum", "Filtres, recherche et période", "Filtri, ricerca e periodo", "フィルター・検索・期間", "筛选、搜索与时间段", "Filtros, pesquisa e período"],
      b: ["Filters pick the kind of event (alert level changes, nodes and cameras online or offline, security mode, alarms, devices, network), the alert level and a period with from and to dates; the search box looks for any text. Combine them to answer questions such as \"which camera went offline last night?\". Remember to clear them when the list looks too short.",
        "Los filtros eligen el tipo de evento (cambios de nivel de alerta, nodos y cámaras en línea o perdidos, modo de seguridad, alarmas, dispositivos, red), el nivel de alerta y un periodo con fechas desde y hasta; el buscador busca cualquier texto. Combínalos para responder cosas como \"¿qué cámara se cayó anoche?\". Acuérdate de quitarlos cuando la lista parezca demasiado corta.",
        "Die Filter wählen die Ereignisart (Warnstufenwechsel, Knoten und Kameras online oder offline, Sicherheitsmodus, Alarme, Geräte, Netz), die Warnstufe und einen Zeitraum mit Von- und Bis-Datum; die Suche sucht beliebigen Text. Kombinieren Sie sie für Fragen wie \"Welche Kamera fiel letzte Nacht aus?\". Denken Sie daran, sie zu löschen, wenn die Liste zu kurz wirkt.",
        "Les filtres choisissent le type d'événement (changements de niveau d'alerte, nœuds et caméras en ligne ou hors ligne, mode de sécurité, alarmes, appareils, réseau), le niveau d'alerte et une période avec dates de début et de fin ; la recherche cherche n'importe quel texte. Combinez-les pour répondre à « quelle caméra est tombée cette nuit ? ». Pensez à les retirer quand la liste semble trop courte.",
        "I filtri scelgono il tipo di evento (cambi di livello di allerta, nodi e telecamere online o offline, modalità di sicurezza, allarmi, dispositivi, rete), il livello di allerta e un periodo con date da e a; la ricerca cerca qualsiasi testo. Combinali per rispondere a \"quale telecamera si è spenta stanotte?\". Ricorda di toglierli quando l'elenco sembra troppo corto.",
        "フィルターで、イベントの種類（警戒レベルの変化、ノード／カメラのオンライン・オフライン、セキュリティモード、アラーム、デバイス、ネットワーク）、警戒レベル、開始日・終了日の期間を選び、検索欄で任意の文字を探せます。組み合わせれば「昨夜どのカメラが落ちたか」にも答えられます。一覧が短すぎると感じたらフィルターを解除してください。",
        "筛选器可选事件类型（警戒级别变化、节点和摄像头上线或离线、安全模式、报警、设备、网络）、警戒级别以及起止日期；搜索框可查找任意文字。组合使用可回答“昨晚哪台摄像头掉线了？”之类的问题。列表显得太短时，记得清除筛选条件。",
        "Os filtros escolhem o tipo de evento (mudanças do nível de alerta, nós e câmaras ligados ou perdidos, modo de segurança, alarmes, dispositivos, rede), o nível de alerta e um período com datas de e até; a pesquisa procura qualquer texto. Combine-os para responder a \"que câmara caiu esta noite?\". Lembre-se de os limpar quando a lista parecer curta demais."] },
    { target: "his-actions", placement: "bottom",
      t: ["Live, older events and clearing", "En vivo, eventos antiguos y borrado", "Live, ältere Ereignisse und Löschen", "En direct, anciens événements et effacement", "Dal vivo, eventi vecchi e cancellazione", "ライブ更新・過去分・消去", "实时、更早事件与清除", "Em direto, eventos antigos e limpeza"],
      b: ["\"Live\" refreshes the list every five seconds and can be paused, so you can read without it moving. \"Load older events\" asks the server for more. \"Clear history\" deletes the stored events but not the alarms, and Studio asks first; there is no undo. It is the only place that tells the whole story, also of alarms you have already acknowledged.",
        "\"En vivo\" refresca la lista cada cinco segundos y se puede pausar para leer sin que se mueva. \"Cargar eventos anteriores\" pide más al servidor. \"Borrar historial\" borra los eventos guardados pero no las alarmas, y Studio pregunta antes; no hay deshacer. Es el único sitio que cuenta toda la historia, también de las alarmas ya reconocidas.",
        "\"Live\" aktualisiert die Liste alle fünf Sekunden und lässt sich pausieren, damit Sie ohne Bewegung lesen. \"Ältere Ereignisse laden\" fragt den Server nach mehr. \"Verlauf löschen\" löscht die gespeicherten Ereignisse, nicht die Alarme, und Studio fragt vorher; es gibt kein Rückgängig. Nur hier steht die ganze Geschichte, auch der bereits quittierten Alarme.",
        "« En direct » rafraîchit la liste toutes les cinq secondes et peut être mis en pause pour lire sans que ça bouge. « Charger les événements plus anciens » en demande davantage au serveur. « Effacer l'historique » supprime les événements conservés mais pas les alarmes, et Studio demande d'abord ; pas d'annulation. C'est le seul endroit qui raconte toute l'histoire, y compris des alarmes déjà acquittées.",
        "\"Dal vivo\" aggiorna l'elenco ogni cinque secondi e si può mettere in pausa per leggere senza che si muova. \"Carica eventi più vecchi\" ne chiede altri al server. \"Cancella cronologia\" elimina gli eventi conservati ma non gli allarmi, e Studio chiede prima; non si può annullare. È l'unico posto che racconta tutta la storia, anche degli allarmi già riconosciuti.",
        "「ライブ」は5秒ごとに一覧を更新し、一時停止すれば動かずに読めます。「過去のイベントを読み込む」でサーバーからさらに取得します。「履歴を消去」は保存済みイベントを削除します（アラームは消えません）。Studioが先に確認しますが、元には戻せません。確認済みのアラームも含む全経緯を見られるのはここだけです。",
        "“实时”每五秒刷新一次列表，可暂停以便不被打断地阅读。“加载更早的事件”向服务器请求更多。“清除历史”会删除已保存的事件，但不会删除报警，Studio 会先询问，且无法撤销。只有这里能看到完整经过，包括已确认的报警。",
        "\"Em direto\" atualiza a lista a cada cinco segundos e pode ser pausado para ler sem que se mexa. \"Carregar eventos anteriores\" pede mais ao servidor. \"Limpar o histórico\" apaga os eventos guardados mas não os alarmes, e o Studio pergunta antes; não há desfazer. É o único sítio que conta a história toda, também dos alarmes já reconhecidos."] },
  ],
};
